const questionBank = [
    { track: "selenium", type: "mcq", topic: "SELENIUM", question: "Which statement best explains the difference between findElement() and findElements()?", options: ["Both return a list, but one is faster", "findElement returns the first match; findElements returns a list and can be empty", "findElements throws when no element is found", "findElement only works with CSS selectors"], answer: 1, explanation: "findElement returns one WebElement and throws NoSuchElementException if there is no match. findElements returns a List<WebElement>; an empty list is the no-match result.", anchor: "Infosys Selenium Q7 / Deloitte R1 Q8" },
    { track: "selenium", type: "mcq", topic: "SELENIUM", question: "A checkout button appears after an API call finishes. What is the strongest default wait strategy?", options: ["Thread.sleep(10_000)", "A long implicit wait everywhere", "An explicit wait for the button to be clickable", "Refresh the page until it appears"], answer: 2, explanation: "Use a condition tied to the behavior you need: WebDriverWait.until(elementToBeClickable(...)). It communicates intent and avoids paying a fixed delay when the app is faster.", anchor: "Infosys Selenium Q8-10 / Deloitte R1 Q9" },
    { track: "selenium", type: "mcq", topic: "SELENIUM", question: "Which Selenium call reads the current value typed into an input box?", options: ["getText()", "getAttribute(\"value\")", "getCssValue(\"text\")", "getInputText()"], answer: 1, explanation: "Inputs render their current content as the value attribute, so getAttribute(\"value\") is the reliable choice. getText() often returns an empty string for input controls.", anchor: "Deloitte R1 Q11" },
    { track: "selenium", type: "mcq", topic: "SELENIUM", question: "What is the correct response when an interviewer asks if Selenium can automate a CAPTCHA?", options: ["Yes, with JavaScriptExecutor", "Yes, by polling until it solves", "No; CAPTCHA is designed to distinguish humans from automation", "Only in headless mode"], answer: 2, explanation: "Say no. The right testing approach is to disable or bypass CAPTCHA in a controlled test environment, or use a test hook—not defeat the security control in production.", anchor: "Infosys Selenium Q25 / Deloitte R2 Q16" },
    { track: "selenium", type: "mcq", topic: "SELENIUM", question: "What is the practical difference between driver.close() and driver.quit()?", options: ["close quits every browser; quit closes one tab", "close closes the current window; quit ends the whole WebDriver session", "They are aliases", "quit only works in headless mode"], answer: 1, explanation: "close() closes the current window or tab. quit() closes every window and ends the session, releasing the driver process.", anchor: "Infosys Selenium Q21" },
    { track: "selenium", type: "mcq", topic: "SELENIUM", question: "You need to type into a JavaScript prompt alert. Which sequence is correct?", options: ["driver.switchTo().alert().sendKeys(\"text\").accept()", "driver.alert().type(\"text\").close()", "driver.switchTo().window(\"alert\").sendKeys(\"text\")", "driver.findElement(Alert.prompt()).sendKeys(\"text\")"], answer: 0, explanation: "Switch to the alert, send keys to the prompt, then accept it: driver.switchTo().alert().sendKeys(\"text\").accept().", anchor: "Deloitte R1 Q12" },
    { track: "selenium", type: "mcq", topic: "SELENIUM", question: "What does a StaleElementReferenceException usually tell you?", options: ["The locator syntax is invalid", "The browser is offline", "The DOM changed and the stored element reference is no longer valid", "The element is hidden by CSS"], answer: 2, explanation: "The WebElement reference was tied to an older DOM. Re-locate the element after the update, and fix the synchronization point that allowed the stale reference.", anchor: "Infosys Selenium Q14" },
    { track: "selenium", type: "written", topic: "SELENIUM", question: "How do you handle flaky Selenium tests? Walk through your diagnosis and fixes.", coach: "Name the top causes (synchronization, test data, environment, order dependence), your diagnosis steps, and why blind retries are a last resort.", model: "First I prove it is actually flaky: run it in isolation and in the suite, and read the failure artifacts—screenshot, DOM, logs. The usual root cause is synchronization, fixed with an explicit wait on the right condition instead of sleeps. Next suspects are shared test data, order dependence, and environment differences like headless vs headed viewport size. I fix the root cause rather than wrapping retries around it—retry logic hides real intermittent product bugs. A quarantine tag keeps a flaky test out of the signal while it is being fixed, so the team keeps trusting a red build.", anchor: "Luxoft high-probability Q11" },
    { track: "selenium", type: "written", topic: "SELENIUM", question: "Explain how you would make a dynamic-element test reliable without using Thread.sleep().", coach: "Cover the condition, the locator, the timeout boundary, and what you would investigate if it still failed.", model: "I would use an explicit WebDriverWait with a stable locator and a condition that matches the next action—for example, wait until the element is visible or clickable. I would keep the timeout local to that behavior, avoid mixing arbitrary sleeps with implicit waits, and investigate the network or DOM state if the condition times out." },
    { track: "java", type: "mcq", topic: "JAVA", question: "Which collection preserves insertion order while using key/value pairs?", options: ["HashMap", "TreeMap", "LinkedHashMap", "Hashtable only"], answer: 2, explanation: "LinkedHashMap maintains a linked list through its entries, so iteration follows insertion order while retaining map semantics.", anchor: "Deloitte R1 Q5" },
    { track: "java", type: "mcq", topic: "JAVA", question: "Which is the best short explanation of method overloading?", options: ["Same method signature, different class", "Same method name with different parameter lists", "Changing a private method at runtime", "Replacing a parent method with a field"], answer: 1, explanation: "Overloading is compile-time polymorphism: same method name, different parameter list. Overriding is a subclass providing a new implementation for the same signature.", anchor: "Infosys Java Q14 / Deloitte R2 Q10" },
    { track: "java", type: "mcq", topic: "JAVA", question: "Which statement about checked exceptions is accurate?", options: ["They are ignored by the compiler", "They must be caught or declared", "They only happen during compilation", "They are the same as Errors"], answer: 1, explanation: "Checked exceptions are verified by the compiler, so code must handle them with catch or declare them with throws. RuntimeException subclasses are unchecked.", anchor: "Infosys Java Q10 / Deloitte R1 Q13" },
    { track: "java", type: "mcq", topic: "JAVA", question: "What is the main reason StringBuilder is preferred for repeated string concatenation in a loop?", options: ["It is immutable", "It avoids creating a new String object for every append", "It automatically sorts characters", "It is thread-safe by default"], answer: 1, explanation: "String is immutable, so repeated concatenation can create many intermediate objects. StringBuilder mutates a character buffer and is the usual single-threaded choice.", anchor: "Infosys Java Q12" },
    { track: "java", type: "mcq", topic: "JAVA", question: "What is the safest first move when asked to reverse a string while preserving whitespace positions?", options: ["Reverse the entire string with StringBuilder.reverse()", "Collect non-whitespace characters, reverse them, then place them back into non-whitespace positions", "Remove all spaces and return the result", "Sort the characters alphabetically"], answer: 1, explanation: "Separate the concerns: preserve the positions where whitespace occurs, reverse only the letters, then rebuild. This is easier to explain and test than trying to patch a reversed string.", anchor: "Deloitte R1 Q2" },
    { track: "java", type: "written", topic: "JAVA", question: "Explain the difference between an exception and an error, then give one example of each.", coach: "Keep it interview-sized: what the JVM means, whether application code normally recovers, and your examples.", model: "An exception is an event an application may handle or communicate, such as IOException or IllegalArgumentException. An Error signals a serious JVM or environment problem, such as OutOfMemoryError; application code generally should not try to recover from it." },
    { track: "framework", type: "mcq", topic: "FRAMEWORK", question: "What should a Page Object primarily own?", options: ["Business assertions for every test", "Locators and user-facing actions for a page structure", "The Maven build file", "All test data for the company"], answer: 1, explanation: "A Page Object hides locator and interaction details behind meaningful actions. Tests should describe behavior and assertions; page objects should model structure and interactions.", anchor: "Infosys Framework Q7 / repo STUDY_GUIDE" },
    { track: "framework", type: "mcq", topic: "FRAMEWORK", question: "If a product has 100 pages, do you automatically create 100 Page Objects?", options: ["Yes, one class per URL is mandatory", "No; model distinct structures and extract reusable components", "No; put every locator in one giant class", "Only if every page has a unique title"], answer: 1, explanation: "Page objects model distinct page structures, not URLs. Shared headers, grids, and templated page layouts can be reusable component or page classes.", anchor: "Deloitte R2 Q2" },
    { track: "framework", type: "mcq", topic: "FRAMEWORK", question: "Which answer best describes a data-driven framework?", options: ["Test logic is generated from random data only", "Test data is separated from test logic so the same flow can run with multiple datasets", "All tests are written in a spreadsheet", "Tests only run against databases"], answer: 1, explanation: "Data-driven design keeps inputs and expected results separate from the test flow, enabling multiple scenarios through a DataProvider, CSV, JSON, database, or similar source.", anchor: "Infosys Framework Q5 / Q8" },
    { track: "framework", type: "mcq", topic: "FRAMEWORK", question: "What is the strongest response when asked to explain your SampleSelenium framework?", options: ["It has many tests and runs in Chrome", "It is Maven + Java 17 + Selenium 4 with POM, explicit waits, ThreadLocal driver lifecycle, JUnit/TestNG/Cucumber drills, and CI", "It uses only manual test cases", "It is a collection of copied scripts"], answer: 1, explanation: "Lead with architecture, then the reason behind each choice: Page Objects reduce locator coupling, explicit waits synchronize behavior, and ThreadLocal supports parallel execution.", anchor: "Repo STUDY_GUIDE: Explain Your Framework" },
    { track: "framework", type: "mcq", topic: "CUCUMBER", question: "In Cucumber, what is the relationship between a feature file, step definitions, and hooks?", options: ["Feature files contain Java code that runs directly", "Gherkin steps in the feature file are matched to annotated Java methods by expression; @Before/@After hooks run around each scenario", "Hooks replace step definitions", "Step definitions must live inside the feature file"], answer: 1, explanation: "The feature file is plain Gherkin (Given/When/Then). Cucumber matches each step to a Java method via cucumber expressions or regex. Hooks (@Before/@After) wrap every scenario—driver setup and teardown live there, not in the steps.", anchor: "Luxoft Q3 / repo Module 8" },
    { track: "framework", type: "mcq", topic: "CUCUMBER", question: "What do Cucumber tags and data tables give you?", options: ["Tags rename scenarios; data tables format the report", "Tags select which scenarios run (@smoke, @regression) and can scope hooks; data tables pass structured multi-row input into a single step", "Both are deprecated Gherkin features", "Tags only work in Jenkins"], answer: 1, explanation: "Tags filter execution (cucumber.filter.tags) and scope hooks like @Before(\"@api\"). A data table arrives in the step method as a DataTable or List<Map<String,String>>—the standard way to feed a step several rows of test data. Scenario Outline + Examples is the related repetition mechanism.", anchor: "Luxoft Q3 / repo Module 8" },
    { track: "framework", type: "mcq", topic: "FRAMEWORK", question: "Which design patterns show up in a typical Java automation framework, and where?", options: ["Only Page Object; nothing else applies", "Page Object for structure, Factory for driver creation, Singleton/ThreadLocal for driver lifecycle, Builder for test data or requests", "MVC everywhere", "Observer for locators"], answer: 1, explanation: "Be ready to point at your own code: Page Object reduces locator coupling, a Factory method creates the right WebDriver per browser, the ThreadLocal DriverManager is Singleton-like per thread, and Builder assembles test data or REST Assured request specs fluently.", anchor: "Luxoft Q10 / repo DriverManager" },
    { track: "framework", type: "mcq", topic: "FRAMEWORK", question: "A new feature ships next sprint. How do you decide what to automate first?", options: ["Automate everything immediately", "Automate whatever is easiest", "Prioritize by risk and repetition: critical business flows, calculation correctness, and stable repetitive regression paths; leave one-off exploratory checks manual", "Only automate UI tests"], answer: 2, explanation: "Highest value first: revenue-critical and calculation-heavy paths, then high-frequency regression. Prefer the API layer where possible—faster and more stable than UI. Volatile UIs and one-time checks are poor automation investments.", anchor: "Luxoft Q12" },
    { track: "framework", type: "mcq", topic: "CI/CD", question: "How does automation typically integrate with Jenkins, and how are results reported?", options: ["Jenkins runs tests manually on request only", "A pipeline stage runs mvn test (headless) on push/PR and nightly; surefire/cucumber reports and failure screenshots are published as artifacts, and the build gates on failures", "Jenkins replaces the test framework", "Results are emailed as raw console logs"], answer: 1, explanation: "The Jenkinsfile (or GitHub Actions) checks out the branch, runs the suite headless, publishes JUnit XML so trends show per-test history, archives screenshots/reports, and fails the build to block a broken merge. Same pipeline nightly for the full regression.", anchor: "Luxoft Q13 / repo Jenkinsfile" },
    { track: "framework", type: "written", topic: "FRAMEWORK", question: "Give your 60-second answer for: Explain your automation framework.", coach: "Use this order: build tool/language → POM → waits → driver lifecycle → data/BDD → reporting/CI. Name why, not just what.", model: "It is a Maven project using Java 17 and Selenium 4. Page Objects hold locators and actions, with BasePage helpers centralizing explicit waits so tests avoid Thread.sleep. DriverManager owns a ThreadLocal WebDriver, which keeps parallel tests isolated. The suite also has TestNG data-driven drills, Cucumber features for business-readable flows, failure screenshots, and CI through GitHub Actions/Jenkins." },
    { track: "testng-sql", type: "mcq", topic: "TESTNG", question: "What does a TestNG DataProvider give you?", options: ["A browser binary", "A way to run the same test with multiple data sets", "A replacement for assertions", "A report server"], answer: 1, explanation: "A DataProvider supplies parameters to a test method, making the scenario reusable across valid, invalid, boundary, or role-based inputs.", anchor: "Infosys TestNG Q6" },
    { track: "testng-sql", type: "mcq", topic: "TESTNG", question: "What is the practical difference between Assert and Verify?", options: ["Assert stops the current flow on failure; verify-style soft assertions collect failures before asserting", "Assert only works for APIs", "Verify always stops immediately", "There is no difference in any framework"], answer: 0, explanation: "A hard assertion fails fast. A soft assertion can collect multiple failures, but you must call assertAll() or the failures may never be reported.", anchor: "Infosys TestNG Q10" },
    { track: "testng-sql", type: "mcq", topic: "SQL", question: "Which query pattern is a standard way to find the second-highest distinct salary?", options: ["SELECT MAX(salary) FROM employees", "SELECT MAX(salary) FROM employees WHERE salary < (SELECT MAX(salary) FROM employees)", "SELECT salary FROM employees ORDER BY salary", "SELECT SECOND(salary) FROM employees"], answer: 1, explanation: "The inner MAX finds the highest salary; the outer query finds the greatest salary below it. Add DISTINCT or adapt the query when duplicates matter.", anchor: "Deloitte R1 Q3 / Infosys SQL Q8" },
    { track: "testng-sql", type: "mcq", topic: "SQL", question: "Which clause filters grouped results after aggregation?", options: ["WHERE", "ORDER BY", "HAVING", "GROUP"], answer: 2, explanation: "WHERE filters rows before grouping. HAVING filters groups after aggregate calculations such as COUNT or SUM.", anchor: "Infosys SQL Q6-7" },
    { track: "testng-sql", type: "mcq", topic: "TESTNG", question: "Why does a ThreadLocal WebDriver help parallel tests?", options: ["It makes the browser faster", "It gives each test thread its own driver reference", "It removes the need for waits", "It runs all tests in one browser"], answer: 1, explanation: "Each thread gets an isolated WebDriver value, preventing one parallel test from switching or quitting another test's browser.", anchor: "Repo STUDY_GUIDE: parallel execution" },
    { track: "testng-sql", type: "mcq", topic: "SQL", question: "How do you reconcile API results against database values?", options: ["Trust the API; the database is an implementation detail", "Query the source tables with SQL, compute the same expected values (aggregates, joins), and assert the API response matches row-by-row and in totals", "Compare row counts only", "Screenshot both and compare visually"], answer: 1, explanation: "Expected-vs-actual reconciliation: run the SQL that defines truth (joins, SUM/GROUP BY), then assert the API's fields and totals against it. Mismatches localize the defect—API layer, calculation service, or data. This is the SDET SQL story.", anchor: "Luxoft Q9 / repo Module 7" },
    { track: "testng-sql", type: "mcq", topic: "SQL", question: "What is SQL injection, and what do you verify as a tester?", options: ["A performance tuning technique", "Malicious input altering a query's structure; verify inputs like ' OR '1'='1 are rejected and that the code uses parameterized queries/prepared statements, not string concatenation", "A way to speed up joins", "A database backup strategy"], answer: 1, explanation: "Classic probe: a login field fed ' OR '1'='1 must not authenticate. The fix you verify in code review is parameterized queries (PreparedStatement / ORM bind variables)—user input must never be concatenated into SQL. Error messages should not leak schema details either.", anchor: "Luxoft interview reports" },
    { track: "interview", type: "mcq", topic: "VOICE", question: "A developer disagrees that a bug should be fixed. What is the most senior first response?", options: ["Escalate immediately without discussion", "Reproduce it, align on expected behavior and impact, then document the evidence and involve the right owner", "Close the bug to preserve velocity", "Argue until the developer agrees"], answer: 1, explanation: "Keep it evidence-first and collaborative: show the reproduction, expected versus actual behavior, risk, and agreed next action. Escalate when the decision or risk needs a higher owner.", anchor: "Deloitte R2 Q14" },
    { track: "interview", type: "mcq", topic: "VOICE", question: "Which three-part structure makes a technical interview answer easiest to follow?", options: ["Definition → example → trade-off", "Jargon → history → apology", "Code → silence → code", "Opinion → opinion → opinion"], answer: 0, explanation: "Start with the crisp definition, ground it in a real example, then show judgment by naming a trade-off or failure mode. This keeps an answer short without sounding shallow.", anchor: "Daily answer protocol" },
    { track: "interview", type: "mcq", topic: "VOICE", question: "When you forget the exact Java method name during a live coding prompt, what is the strongest move?", options: ["Stop speaking until you remember", "Say the pattern and intent, state you would verify the exact API, and keep working", "Invent a method name confidently", "Change the problem"], answer: 1, explanation: "Interviewers are evaluating reasoning as well as syntax. Narrate the invariant, data structure, and edge cases while being honest about the exact method name.", anchor: "Repo STUDY_GUIDE: Live-Interview Reminders" },
    { track: "api", type: "mcq", topic: "API", question: "A POST to /api/trades successfully creates a new trade. Which response is correct per REST semantics?", options: ["200 OK with the trade in the body", "201 Created with a Location header pointing at the new trade's URI", "204 No Content", "202 Accepted with no follow-up"], answer: 1, explanation: "201 means a new resource now exists because of this request, and it should carry a Location header with the new resource's URI. A POST-create that returns 200 is a defect worth filing—clients and gateways key off the semantics.", anchor: "Repo Module 9 / the 200-vs-201 question" },
    { track: "api", type: "mcq", topic: "API", question: "What is the difference between HTTP 401 and 403?", options: ["They are interchangeable auth errors", "401 means unauthenticated (who are you?); 403 means authenticated but forbidden (you may not)", "401 is a server error; 403 is a client error", "403 means the token expired; 401 means the endpoint moved"], answer: 1, explanation: "401 says credentials are missing or invalid—retrying WITH credentials can succeed. 403 says the server knows who you are and still refuses—retrying won't help. Test both: no token, and a valid token for the wrong role.", anchor: "Repo Module 9 / SourceD09ApiDrills" },
    { track: "api", type: "mcq", topic: "API", question: "Which HTTP methods are idempotent?", options: ["GET, PUT, DELETE — repeating them leaves the same end state", "POST and PUT only", "All of them", "None; HTTP has no idempotency concept"], answer: 0, explanation: "GET, PUT, and DELETE produce the same end state no matter how many times you repeat them. POST is NOT idempotent—each call can create another resource. Retry logic and test cleanup both depend on knowing this.", anchor: "Repo Module 9 / idempotency talk track" },
    { track: "api", type: "mcq", topic: "API", question: "A calculation engine queues a long-running valuation request instead of computing it inline. Which status fits the initial response?", options: ["200 OK with the final result", "201 Created", "202 Accepted, with a way to poll for the result", "504 Gateway Timeout"], answer: 2, explanation: "202 Accepted means the request was valid and queued for asynchronous processing—common in calc-intensive services. The test then polls a status endpoint or result URI until the computation completes.", anchor: "Repo Module 9 / status-code family" },
    { track: "api", type: "mcq", topic: "API", question: "In REST Assured, which chain correctly asserts a status code and a JSON field?", options: ["driver.get(url).assertStatus(200)", "given().when().get(\"/api/trades/1001\").then().statusCode(200).body(\"instrument\", equalTo(\"AAPL\"))", "restAssured.fetch(url).expect(200)", "new Response(url).jsonPath().assert(200)"], answer: 1, explanation: "The given/when/then DSL: given() sets up headers and body, when() makes the call, then() asserts status, headers, and body via Hamcrest matchers with GPath expressions like totals.grossMarketValue.", anchor: "Repo Module 9 / SourceD09ApiDrills" },
    { track: "api", type: "mcq", topic: "API", question: "How do you validate a large JSON response of financial calculations beyond spot-checking one field?", options: ["Assert the response is not null", "Compare the raw string to a saved copy", "Extract the arrays and recompute the math—each position's marketValue = quantity × price, and the reported total = the sum you recompute", "Check only the HTTP status code"], answer: 2, explanation: "Recompute the business math in the test: per-row derived values and the aggregate totals. String comparison breaks on field order and formatting; a null check proves nothing about correctness.", anchor: "Repo Module 9 / portfolioValuationJsonRecomputesToItsOwnTotals" },
    { track: "api", type: "mcq", topic: "API", question: "What is a POJO request model in Java API automation?", options: ["A browser page object used for UI locators", "A simple Java class representing the request body so a mapper can serialize it to JSON", "A database table that stores API requests", "A Cucumber feature file written in Java"], answer: 1, explanation: "A POJO request model gives the JSON body a typed Java representation. Jackson or REST Assured serializes the object into JSON, which is more reusable and maintainable than embedding raw JSON strings in every test.", anchor: "Luxoft API follow-up / d09_api" },
    { track: "api", type: "mcq", topic: "API", question: "How would you deserialize a JSON array response into TradeResult POJOs?", options: ["Use driver.findElements()", "Use ObjectMapper.readValue(json, new TypeReference<List<TradeResult>>() {}) or REST Assured extract().as(new TypeRef<List<TradeResult>>() {})", "Compare the raw JSON string with ==", "Convert the response to HTML first"], answer: 1, explanation: "Jackson maps the JSON fields into typed Java objects. With REST Assured, extract().as(new TypeRef<List<TradeResult>>() {}) gives a list of POJOs that can be used for field-level and business-rule assertions.", anchor: "Luxoft API follow-up / d09_api" },
    { track: "api", type: "mcq", topic: "SPRING BOOT", question: "What does @WebMvcTest with MockMvc give you when testing a Spring Boot controller?", options: ["A full application context with a real HTTP port", "A controller-slice test: only the web layer loads, services are mocked with @MockBean, no server socket needed", "A browser-based UI test", "A database integration test"], answer: 1, explanation: "@WebMvcTest loads only the web layer, so it is fast. mockMvc.perform(post(...)).andExpect(status().isCreated()) asserts status and JSON without starting a server. @SpringBootTest(webEnvironment = RANDOM_PORT) is the full-context alternative.", anchor: "Repo Module 9 / Spring Boot testing talk track", employers: ["luxoft"] },
    { track: "api", type: "mcq", topic: "SPRING BOOT", question: "Your microservice under test calls three downstream microservices. How do you test it in isolation?", options: ["Always test against the full integrated environment", "Stub the downstream HTTP dependencies with WireMock, and use consumer-driven contract tests (Pact / Spring Cloud Contract) to catch breaking API changes", "Mock the entire service under test", "Skip those code paths"], answer: 1, explanation: "WireMock replaces the downstream services with programmable HTTP stubs, so tests are fast and deterministic. Contract tests then verify both sides of each service boundary independently, catching breaking changes before integration environments do.", anchor: "Repo Module 9 / microservices talk track" },
    { track: "api", type: "mcq", topic: "API", question: "Beyond the HTTP status code, what do you validate in an API response?", options: ["Nothing; 200 means it works", "Headers (Content-Type, Location, caching), body correctness against the contract/schema, error-body shape on negative paths, response time SLA, and resulting state (DB or a follow-up GET)", "Only that the body is valid JSON", "The server's IP address"], answer: 1, explanation: "Status is the weakest signal. Validate the contract: headers, every business-relevant field (recompute calculations), schema/required fields, negative-path error bodies, response time, and the side effect—did the resource actually persist?", anchor: "Luxoft Q5 / repo Module 9" },
    { track: "api", type: "mcq", topic: "API", question: "How do you handle rounding and precision when asserting financial calculations in Java tests?", options: ["Compare doubles with ==", "Use BigDecimal (or an explicit tolerance/delta) with a stated rounding mode; never trust double equality for money", "Round everything to integers", "Convert to String and compare"], answer: 1, explanation: "Binary floating point cannot represent most decimal fractions, so 0.1 + 0.2 != 0.3 as doubles. Assert money with BigDecimal.compareTo and the spec's rounding mode (e.g. HALF_UP to 2 decimals), or with an explicit delta. Pair this with boundary, null, and invalid-input negative tests.", anchor: "Luxoft Q8" },
    { track: "api", type: "mcq", topic: "API", question: "What negative and boundary cases matter most for a financial calculation endpoint?", options: ["Only the happy path with round numbers", "Zero and negative quantities, min/max values, nulls and missing fields, malformed JSON, wrong data types, and currency/precision edge amounts — each with the correct 4xx and a useful error body", "Random strings only", "Whatever the developer suggests"], answer: 1, explanation: "Calc engines fail at the edges: zero/negative inputs, overflow-scale values, missing or null fields (400/422 with a field-level error, never a 500), type mismatches, and amounts that stress rounding like 0.005. The error body is part of the contract—assert it.", anchor: "Luxoft Q8 / repo Module 9" },
    { track: "api", type: "mcq", topic: "PERFORMANCE", question: "How would you performance-test a calculation-heavy service with JMeter?", options: ["Open the UI and time it with a stopwatch", "Build a thread group hitting the calc endpoints with realistic parameterized payloads, ramp up load, and assert against SLAs on p90/p95 latency, throughput, and error rate; then push past expected load for stress", "Run the functional suite twice", "JMeter only tests databases"], answer: 1, explanation: "Load test = expected concurrency vs SLA; stress test = increase until it breaks to find the ceiling; soak/endurance = sustained load hunting leaks. Use CSV data sets so every thread sends different calculation inputs, and watch percentiles, not averages.", anchor: "Luxoft Q14" },
    { track: "api", type: "written", topic: "API", question: "What is a POJO request model, and why would you use one instead of a raw JSON string?", coach: "Define POJO, explain serialization, and connect it to maintainability and type safety.", model: "A POJO request model is a simple Java class whose fields represent the API request body. Jackson or REST Assured serializes it to JSON. I would use it for type safety, reusable test data, clearer failures, and easier maintenance when the contract changes. I would use BigDecimal for financial amounts and annotations such as @JsonProperty when Java and JSON names differ.", anchor: "Luxoft API follow-up / d09_api" },
    { track: "api", type: "written", topic: "API", question: "How would you deserialize API JSON into TradeResult POJOs?", coach: "Mention Jackson, a list TypeReference, field mapping, and the financial-amount type.", model: "I would use Jackson directly with ObjectMapper.readValue(json, new TypeReference<List<TradeResult>>() {}) or REST Assured extraction with new TypeRef<List<TradeResult>>() {}. The TradeResult class would have fields, constructors, getters/setters, and BigDecimal for amount. Jackson maps matching JSON names automatically; @JsonProperty handles differences and @JsonIgnoreProperties can handle nonessential fields.", anchor: "Luxoft API follow-up / d09_api" },
    { track: "api", type: "written", topic: "API", question: "How would you call a Spring Boot endpoint with REST Assured?", coach: "Use the given/when/then structure, then add the follow-ups: auth, headers, POJO body, response mapping, and negative cases.", model: "I would configure a reusable request specification for the base URI, authentication, common headers, and logging. The test would use given() to add headers, query parameters, and a POJO body; when() to call get or post; and then() to assert status, content type, headers, response fields, and the business result. I would extract the response as a POJO when later assertions or database reconciliation need typed data.", anchor: "Luxoft API follow-up / d09_api", employers: ["luxoft"] },
    { track: "api", type: "written", topic: "JAVA", question: "Walk through the financial API coding exercise: calculate settled totals by currency from a List<TradeResult>.", coach: "Talk first: filter statuses, validate IDs and amounts, use BigDecimal, aggregate with a map, then name unit tests.", model: "I would first clarify the rules and validate null records, duplicate IDs, missing currencies, and invalid amounts. Then I would filter to SETTLED records and aggregate amounts in a Map<String, BigDecimal>, using BigDecimal rather than double. I would test multiple currencies, failed and cancelled trades, duplicate IDs, zero or negative amounts, nulls, and precision or rounding boundaries.", anchor: "Luxoft possible technical coding exercise" },
    { track: "api", type: "written", topic: "SPRING BOOT", question: "How would you structure an automation framework for testing Spring Boot services?", coach: "Layers, not tools: project layout, request/client layer, data layer, BDD layer, config, CI. Name what owns what.", model: "A Maven/Java project mirroring the framework I own now, aimed at services instead of pages. A client layer wraps REST Assured request specifications per service—base URI, auth, serialization—so steps never build raw requests, the same role page objects play in UI automation. POJOs model request and response payloads, a validation layer handles JSON assertions and recomputes financial calculations, and a JDBC/SQL helper reconciles against the database. On top sits Cucumber: features describe business flows, step definitions call the client layer, hooks manage environment config and test data. Environments are property-driven, and the whole thing runs headless in Jenkins per push with cucumber and surefire reports published.", anchor: "Luxoft Q2", employers: ["luxoft"] },
    { track: "api", type: "written", topic: "API", question: "Explain the difference between HTTP 200 and 201, and what you would do if a create endpoint returned the wrong one.", coach: "Cover the semantics of each, the Location header, and the defect conversation—why it matters to clients, not just pedantry.", model: "Both are success codes. 200 OK is generic success with the result in the body—a GET, a PUT update, a search. 201 Created means a new resource now exists because of this request; it is the correct response to a creating POST and should include a Location header with the new resource's URI. If POST /trades returned 200, I would file a defect: API consumers and gateways key off the status semantics, and a missing Location header breaks clients that follow it to the new resource." },
    { track: "api", type: "written", topic: "SPRING BOOT", question: "How would you approach end-to-end API testing for a microservices-based application?", coach: "Layer your answer: per-service tests, stubbed dependencies, contract tests, then a thin end-to-end layer. Name the tools at each layer.", model: "I test each service black-box through its REST API with REST Assured—status codes, headers, and JSON body validation, including recomputing business calculations in large responses. Downstream services get stubbed with WireMock so the tests are deterministic, and consumer-driven contract tests catch breaking changes between services. Database state is verified with SQL. On top of that sits a thin end-to-end suite through the real integration environment for the critical flows only, because full-stack tests are the slowest and flakiest layer. Performance is separate: JMeter thread groups against the same endpoints." },
    { track: "interview", type: "mcq", topic: "PROCESS", question: "What is the difference between retesting and regression testing?", options: ["They are the same activity", "Retesting verifies a specific fixed defect; regression testing verifies the fix (or any change) did not break existing behavior elsewhere", "Regression only happens before release day", "Retesting is automated; regression is always manual"], answer: 1, explanation: "Retesting targets the exact failed case after a fix. Regression sweeps the surrounding functionality for collateral damage—which is why the regression suite is the primary automation investment.", anchor: "Luxoft interview reports / STLC" },
    { track: "interview", type: "written", topic: "VOICE", question: "Tell me about a serious defect you found and how you communicated the release risk.", coach: "Use a real story: how you found it, how you proved impact (severity vs priority), who you told, what data you brought, and what the decision was.", model: "Structure the story: I found a defect in a critical flow late in the cycle, reproduced it reliably, and quantified the impact—which users, which data, how often. I separated severity from priority, brought evidence rather than opinion—reproduction steps, logs, the affected calculation—and raised it to the decision owners with options: fix now, ship with a documented workaround, or hold the release. My job was to make the risk visible and let the business make an informed call; I documented the decision and added a regression test so it could never return silently.", anchor: "Luxoft Q15" },
    { track: "interview", type: "written", topic: "VOICE", question: "How would you answer: Tell me about yourself and your QA responsibilities in 90 seconds?", coach: "Connect your experience to this role: automation scope, validation depth, framework ownership, and the value you create.", model: "I am a QA/SDET professional focused on turning risk into repeatable validation. My work spans UI automation with Selenium, API and data checks, framework patterns, and CI feedback. I focus on reliable signals—stable locators, meaningful waits, clear assertions, and evidence when a failure is real. In this role I would bring that same approach to expanding coverage while keeping the suite maintainable and useful to the team." }
,
    { track: "selenium", type: "mcq", topic: "SELENIUM", question: "What are the components of the Selenium suite today?", options: ["WebDriver, IDE, and Grid", "Only WebDriver", "RC, Core, and Postman", "JMeter and Cucumber"], answer: 0, explanation: "WebDriver drives the browser via each browser's native driver, IDE records/plays back for prototyping, and Grid distributes tests across machines/browsers. Selenium RC is retired—WebDriver replaced its JavaScript-injection approach with native browser automation (the W3C WebDriver protocol in Selenium 4).", anchor: "Infosys Selenium Q2/Q4" },
    { track: "selenium", type: "mcq", topic: "SELENIUM", question: "Which locator is generally fastest, and why?", options: ["XPath, because it is the most powerful", "By.id — browsers optimize document.getElementById, and ids should be unique", "By.linkText", "CSS class name, always"], answer: 1, explanation: "By.id maps to the browser's fastest native lookup and is the most stable when ids are unique and not auto-generated. Practical order of preference: id, name, CSS, then XPath.", anchor: "Infosys Selenium Q6" },
    { track: "selenium", type: "mcq", topic: "SELENIUM", question: "What makes a FluentWait different from a standard WebDriverWait?", options: ["It is an implicit wait", "You explicitly configure the polling interval and which exceptions to ignore while waiting", "It never times out", "It only works on alerts"], answer: 1, explanation: "FluentWait lets you tune withTimeout, pollingEvery, and ignoring(NoSuchElementException.class). WebDriverWait actually extends FluentWait with a default 500ms poll—know that relationship.", anchor: "Infosys Selenium Q10" },
    { track: "selenium", type: "mcq", topic: "SELENIUM", question: "How do you interact with an element inside an iframe?", options: ["Just findElement; frames are transparent", "driver.switchTo().frame(locator/index/name) first, then locate; switchTo().defaultContent() to come back", "Use JavaScriptExecutor only", "Open the frame URL in a new tab"], answer: 1, explanation: "WebDriver scopes lookups to the current browsing context. Switch into the frame (by index, name/id, or WebElement), interact, then defaultContent() to return to the top document (parentFrame() goes up one level).", anchor: "Infosys Selenium Q12" },
    { track: "selenium", type: "mcq", topic: "SELENIUM", question: "A click opens a new window. How do you continue the test there?", options: ["Selenium follows the new window automatically", "Capture getWindowHandle(), loop getWindowHandles(), switchTo().window(theNewHandle), and switch back when done", "Press Alt+Tab via Actions", "Restart the driver"], answer: 1, explanation: "Save the original handle, iterate the handle set to find the new one, and switchTo().window(handle). Selenium 4 also offers driver.switchTo().newWindow(WindowType.TAB) to open one deliberately.", anchor: "Infosys Selenium Q13" },
    { track: "selenium", type: "mcq", topic: "SELENIUM", question: "XPath vs CSS selector — which trade-off is real?", options: ["CSS can traverse to parent elements; XPath cannot", "XPath can traverse UP the DOM and match by text(); CSS is often faster and more readable but only goes down", "XPath only works in Firefox", "They are identical in capability"], answer: 1, explanation: "XPath supports parent/ancestor axes and text() matching—things CSS cannot do. CSS tends to be faster and easier to read, so prefer it until you need XPath's power.", anchor: "Infosys Selenium Q16" },
    { track: "selenium", type: "mcq", topic: "SELENIUM", question: "Absolute vs relative XPath — why does everyone use relative?", options: ["Absolute is not valid syntax anymore", "Absolute (/html/body/div[2]/...) breaks when ANY ancestor changes; relative (//input[@id='user']) anchors on a stable attribute", "Relative is faster to type only", "Absolute cannot find nested elements"], answer: 1, explanation: "An absolute path encodes the entire DOM chain, so any layout change breaks it. A relative XPath anchors on the nearest stable attribute, surviving structural churn.", anchor: "Infosys Selenium Q17" },
    { track: "selenium", type: "mcq", topic: "SELENIUM", question: "How do you perform drag-and-drop or hover actions?", options: ["sendKeys with arrow characters", "The Actions class: new Actions(driver).dragAndDrop(source, target).perform(), or moveToElement() for hover — don't forget perform()", "driver.drag(source, target)", "Only possible with AutoIt"], answer: 1, explanation: "Actions builds composite gestures: dragAndDrop, moveToElement (hover), contextClick (right-click), doubleClick, keyDown chords. The classic bug is forgetting .perform()—nothing executes without it.", anchor: "Infosys Selenium Q19-20" },
    { track: "selenium", type: "mcq", topic: "SELENIUM", question: "How do you capture a screenshot in Selenium?", options: ["driver.snapshot()", "Cast the driver: ((TakesScreenshot) driver).getScreenshotAs(OutputType.FILE), then copy the file into the report", "Print-screen via Robot only", "Screenshots require Selenium Grid"], answer: 1, explanation: "The driver implements TakesScreenshot. In a framework this lives in an ITestListener/JUnit extension that fires on failure automatically, naming the file after the test. WebElement.getScreenshotAs captures a single element.", anchor: "Infosys Selenium Q22" },
    { track: "selenium", type: "mcq", topic: "SELENIUM", question: "How do you select an option from a standard <select> dropdown?", options: ["Click it and type the value blindly", "Wrap it: new Select(element), then selectByVisibleText / selectByValue / selectByIndex", "JavaScriptExecutor is required", "sendKeys always works for any dropdown"], answer: 1, explanation: "The Select class only works on real <select> tags and offers the three selectBy methods plus getOptions/isMultiple. Custom JS dropdowns (divs) need click-then-click with explicit waits instead.", anchor: "Infosys Selenium Q23" },
    { track: "selenium", type: "mcq", topic: "SELENIUM", question: "When is JavaScriptExecutor the right tool?", options: ["As the default for every click, it's faster", "As a deliberate fallback: scrolling into view, reading JS state, or clicking an element the normal API can't reach — while noting it bypasses user-realistic interaction", "Never; it is deprecated", "Only for alerts"], answer: 1, explanation: "((JavascriptExecutor) driver).executeScript(...) escapes WebDriver's user-simulation. Useful for scrollIntoView or stubborn overlays, but a JS click passes even when a real user couldn't click—so it can hide product bugs. Say that trade-off out loud.", anchor: "Infosys Selenium Q24" },
    { track: "java", type: "mcq", topic: "JAVA", question: "Name the four OOP pillars and the one-line meaning of each.", options: ["Compilation, execution, debugging, deployment", "Encapsulation (hide state behind methods), Inheritance (is-a reuse), Polymorphism (one interface, many forms), Abstraction (expose what, hide how)", "Classes, objects, packages, imports", "Speed, safety, syntax, style"], answer: 1, explanation: "Have a framework example ready for each: BasePage encapsulates waits, page classes inherit from it, an overridden method or WebDriver interface reference is polymorphism, and the page-object API abstracts locator details from tests.", anchor: "Infosys Java Q2-6" },
    { track: "java", type: "mcq", topic: "JAVA", question: "Array vs ArrayList — the key differences?", options: ["No difference since Java 8", "Array is fixed-length and holds primitives directly; ArrayList grows dynamically, holds objects (autoboxing for primitives), and has rich methods", "ArrayList is fixed size", "Arrays cannot hold objects"], answer: 1, explanation: "Arrays: fixed size, primitives allowed, .length field. ArrayList: resizable, objects only, .size() method, add/remove/contains. In test code ArrayList (via the List interface) is the usual default.", anchor: "Infosys Java Q7" },
    { track: "java", type: "mcq", topic: "JAVA", question: "List vs Set — when do you reach for each?", options: ["They are interchangeable", "List keeps insertion order and allows duplicates; Set enforces uniqueness — e.g. dedupe check: assert list.size() == new HashSet<>(list).size()", "Set keeps duplicates sorted", "List cannot be iterated"], answer: 1, explanation: "That one-liner—comparing a List's size to the Set built from it—is a classic SDET idiom for asserting no duplicate rows/ids came back from an API or grid.", anchor: "Infosys Java Q8" },
    { track: "java", type: "mcq", topic: "JAVA", question: "final vs finally vs finalize?", options: ["Three spellings of the same keyword", "final = no reassignment/override/extension; finally = always-runs cleanup block after try/catch; finalize = deprecated pre-GC hook", "finally runs only when an exception is thrown", "final makes a class garbage-collected sooner"], answer: 1, explanation: "final is a modifier (constants, unoverridable methods, unextendable classes). finally is the cleanup block—driver.quit() belongs there or in try-with-resources. finalize() was a GC callback, deprecated—say you'd never use it.", anchor: "Infosys Java Q11" },
    { track: "java", type: "mcq", topic: "JAVA", question: "String vs StringBuilder vs StringBuffer?", options: ["All three are immutable", "String is immutable; StringBuilder is a mutable buffer (single-threaded default); StringBuffer is the synchronized, thread-safe, slower variant", "StringBuffer is immutable", "StringBuilder is thread-safe"], answer: 1, explanation: "Immutability means every String concat creates a new object. StringBuilder mutates in place—the loop-concatenation choice. StringBuffer predates it with synchronized methods; mention you'd rarely need it in test code.", anchor: "Infosys Java Q12" },
    { track: "java", type: "mcq", topic: "JAVA", question: "HashMap vs Hashtable?", options: ["Hashtable is the modern replacement for HashMap", "HashMap is unsynchronized and allows one null key; Hashtable is legacy, synchronized, and forbids nulls — use ConcurrentHashMap when you need thread safety", "HashMap cannot store nulls", "They differ only in package name"], answer: 1, explanation: "The senior twist: don't say 'use Hashtable for threads'—say ConcurrentHashMap, which locks at bucket level instead of every method. Hashtable is a legacy class you'd only meet in old code.", anchor: "Infosys Java Q20" },
    { track: "testng-sql", type: "mcq", topic: "TESTNG", question: "In what order do TestNG's Before annotations fire?", options: ["Random order each run", "@BeforeSuite → @BeforeTest → @BeforeClass → @BeforeMethod (After* unwinds in reverse)", "@BeforeMethod always first", "Alphabetical order"], answer: 1, explanation: "Outside-in: suite, then <test> tag, then class, then each method. @BeforeTest belongs to the testng.xml <test> block—not to each @Test method, which is the classic trap in this question.", anchor: "Infosys TestNG Q2-3" },
    { track: "testng-sql", type: "mcq", topic: "TESTNG", question: "What do priority and dependsOnMethods do in TestNG?", options: ["Both randomize execution", "priority orders independent tests (lower runs first); dependsOnMethods declares a real dependency — the dependent test is SKIPPED, not failed, if the prerequisite fails", "priority makes tests run in parallel", "dependsOnMethods retries failures"], answer: 1, explanation: "priority is ordering only. dependsOnMethods encodes a genuine prerequisite (login before checkout) and skips downstream tests when it breaks—keeping the report honest about one root cause instead of a cascade of failures.", anchor: "Infosys TestNG Q4-5" },
    { track: "testng-sql", type: "mcq", topic: "TESTNG", question: "How do you re-run only the failed tests after a TestNG run?", options: ["Delete the passed tests", "Run the auto-generated testng-failed.xml from test-output, or wire an IRetryAnalyzer for automatic in-run retries", "TestNG cannot do this", "Rename the failing methods"], answer: 1, explanation: "TestNG writes testng-failed.xml after every suite run containing only the failures. IRetryAnalyzer is the in-run alternative—mention retries should be a diagnostic aid, not a flakiness blanket.", anchor: "Infosys TestNG Q7" },
    { track: "testng-sql", type: "mcq", topic: "TESTNG", question: "What is grouping in TestNG for?", options: ["Formatting the HTML report", "Tagging tests with groups = {\"smoke\"} and selecting them in testng.xml <include> — slicing one suite into smoke/regression/api runs without new classes", "Grouping browsers", "It only works with DataProviders"], answer: 1, explanation: "Groups are TestNG's answer to Cucumber tags: cross-cutting labels selected at suite level. A method can belong to several groups, and CI jobs pick the slice they need.", anchor: "Infosys TestNG Q8" },
    { track: "framework", type: "mcq", topic: "FRAMEWORK", question: "What is a hybrid framework?", options: ["A framework that tests mobile and web", "One combining multiple styles — e.g. Page Object structure with data-driven inputs and keyword/BDD layers — which is what most real frameworks are", "Half manual, half automated", "A framework with two programming languages"], answer: 1, explanation: "Interviewers want you to map the textbook labels onto YOUR framework: POM for structure, DataProviders/CSV for data-driven, Cucumber as the behavior layer. Say 'mine is hybrid' and name the ingredients.", anchor: "Infosys Framework Q4-6" },
    { track: "framework", type: "mcq", topic: "FRAMEWORK", question: "What roles do Maven play in your automation project?", options: ["It is only a downloader", "Dependency management (pom.xml pulls Selenium/TestNG versions), standard lifecycle (compile/test), and Surefire runs the suite — the same command works locally and in CI", "It replaces Jenkins", "It writes the tests"], answer: 1, explanation: "pom.xml declares versions once, transitively resolves libraries, and mvn test compiles then executes via the Surefire plugin. Profiles switch configurations (e.g. a parallel TestNG suite) from the command line.", anchor: "Infosys Framework Q12" },
    { track: "framework", type: "mcq", topic: "FRAMEWORK", question: "How do you run a specific test from the command line?", options: ["You must use the IDE", "mvn test -Dtest=LoginTests#loginWithValidCredentials, plus -D system properties for runtime switches like -Dheadless=true", "java TestFile.java", "mvn deploy"], answer: 1, explanation: "-Dtest targets a class or single method; system properties feed runtime configuration the framework reads (headless, environment, browser). This is also exactly what the CI pipeline invokes.", anchor: "Infosys Framework Q15" },
    { track: "api", type: "mcq", topic: "API", question: "GET vs POST — the differences that matter?", options: ["GET is newer than POST", "GET reads — parameters in the URL, no body, safe/idempotent/cacheable; POST submits a body to create or process — not idempotent, never cacheable by default", "POST cannot carry JSON", "GET is more secure for passwords"], answer: 1, explanation: "Also say the security angle: sensitive data never goes in a GET query string (it lands in logs and history). And the testing angle: repeating a GET is free; repeating a POST may create duplicates.", anchor: "Infosys API Q3" },
    { track: "api", type: "mcq", topic: "API", question: "How does token-based authentication work in API testing?", options: ["Send the password on every request", "Authenticate once to receive a token (often a JWT), send it as Authorization: Bearer <token> on each call, and test expiry/invalid/missing-token paths", "Tokens are only for UIs", "Base64-encode the URL"], answer: 1, explanation: "The framework logs in once in a hook, stores the token, and injects the Authorization header into every request spec. Negative tests: expired token (401), tampered token (401), valid token wrong role (403).", anchor: "Infosys API Q9-10" },
    { track: "testng-sql", type: "mcq", topic: "SQL", question: "Primary key vs foreign key?", options: ["Both allow duplicates", "Primary key uniquely identifies a row (no nulls, no duplicates); a foreign key references another table's primary key, enforcing referential integrity", "Foreign keys must be unique", "Primary keys can be null once"], answer: 1, explanation: "Testing angle: referential integrity is checkable—orphaned child rows (a trade pointing at a missing account) are a data-layer defect an SDET can catch with one LEFT JOIN ... WHERE parent IS NULL query.", anchor: "Infosys SQL Q2-3" },
    { track: "testng-sql", type: "mcq", topic: "SQL", question: "What is an index, and what is the trade-off?", options: ["A backup of the table", "A lookup structure that speeds up reads on the indexed columns, at the cost of slower writes and extra storage", "It makes writes faster", "A synonym for primary key"], answer: 1, explanation: "Like a book index: fast lookup without scanning every page, but every insert/update must also maintain the index. Related follow-up: normalization organizes tables to remove redundancy (1NF/2NF/3NF).", anchor: "Infosys SQL Q9-10" },
    { track: "interview", type: "mcq", topic: "PROCESS", question: "Severity vs priority — and give the classic mismatch examples.", options: ["They are synonyms", "Severity = technical impact (QA assesses); priority = business urgency of fixing (product decides). Crash in a dead feature: high severity, low priority. Typo in the company logo: low severity, high priority", "Priority is always higher than severity", "Developers set both"], answer: 1, explanation: "Always give both cross-examples—that is what proves you understand the distinction rather than reciting it.", anchor: "Infosys Manual Q5" },
    { track: "interview", type: "mcq", topic: "PROCESS", question: "Smoke vs sanity testing?", options: ["Identical activities", "Smoke: broad-and-shallow check that a new build's critical paths work at all (gate before deeper testing); sanity: narrow-and-deep check that a specific fix or change behaves before full regression", "Sanity is always automated; smoke never is", "Smoke tests only run in production"], answer: 1, explanation: "Wide-vs-deep is the memorable frame. Smoke answers 'is this build testable?'; sanity answers 'did this specific change land correctly?'", anchor: "Infosys Manual Q7-8" },
    { track: "interview", type: "mcq", topic: "PROCESS", question: "Walk through the bug life cycle.", options: ["Found → fixed, nothing else", "New → Assigned → Open/In-progress → Fixed → Retest → Verified → Closed, with branches for Rejected, Duplicate, Deferred, and Reopened when the retest fails", "Bugs skip straight to Closed", "The tester closes bugs without retesting"], answer: 1, explanation: "The states matter less than who owns each transition: QA verifies the fix before Closed, and Reopened is QA's lever when a fix doesn't hold. In JIRA these are workflow statuses.", anchor: "Infosys Manual Q4" },
    { track: "java", type: "mcq", topic: "JAVA", question: "What do the static and this keywords mean in Java?", options: ["static means unchangeable; this creates an object", "static members belong to the class, not any instance (shared across objects, no this available); this refers to the current instance — disambiguating fields from parameters or chaining constructors", "this only works in main()", "They are interchangeable"], answer: 1, explanation: "Framework examples to cite: a static WebDriverWait utility or By constants belong to the class; this.driver = driver in a page object constructor is the everyday use of this. Bonus: static methods can't touch instance fields — that's why main() can't use this.", anchor: "Barclays R1 Q7" },
    { track: "selenium", type: "mcq", topic: "SELENIUM", question: "How should Selenium scripts handle exceptions?", options: ["Wrap everything in one try/catch that swallows all exceptions", "Catch only where you can add value (retry a stale element, attach a screenshot, wrap in a clearer message); otherwise let the test FAIL loudly — a swallowed exception is a fake green", "Use System.exit(1) in every catch block", "Selenium never throws exceptions"], answer: 1, explanation: "Know the common ones and their meaning: NoSuchElement (locator/sync), StaleElementReference (DOM refresh), TimeoutException (wait expired), ElementClickIntercepted (overlay). Handle at the framework layer — a listener that screenshots on failure — not with per-line try/catch noise.", anchor: "Barclays R1 Q9" },
    { track: "selenium", type: "mcq", topic: "SELENIUM", question: "How do you run cross-browser tests?", options: ["Rewrite the suite per browser", "Parameterize browser choice (system property or testng.xml parameter) into a driver factory, and scale out via Selenium Grid or a cloud provider — same tests, different capabilities", "Only Chrome can be automated", "Install every browser on your laptop and run sequentially forever"], answer: 1, explanation: "The driver factory reads the browser parameter and returns the right driver (WebDriverManager handles binaries). Grid/cloud (Selenium Grid, Sauce Labs, BrowserStack) runs the same suite across browser/OS combinations in parallel — pairs with the ThreadLocal driver answer.", anchor: "Barclays R2 Q10" },
    { track: "framework", type: "mcq", topic: "FRAMEWORK", question: "How do you manage test data and environment configurations?", options: ["Hard-code them in each test", "Externalize both: environment settings in property/YAML files or CI variables selected by a runtime flag (-Denv=qa); test data in DataProviders, CSV/Excel/JSON, or builders — never hard-coded in test logic", "Keep them in the developer's head", "One shared production account for everything"], answer: 1, explanation: "The seniority markers: secrets come from the CI vault (never committed), tests create-or-clean their own data where possible for independence, and the same suite runs against any environment by switching one flag.", anchor: "Barclays R2 Q2 / Infosys Framework Q8" },
    { track: "framework", type: "mcq", topic: "FRAMEWORK", question: "What practices keep automation scripts maintainable?", options: ["Copy-paste working tests and tweak them", "DRY through page objects and shared utilities, explicit waits centralized in a base class, meaningful names, small independent tests, one logical assertion focus, code review for test code, and deleting dead tests", "Longer tests that cover everything at once", "Comments explaining every line"], answer: 1, explanation: "The theme is: treat test code like production code. Locator changes touch one file, tests don't depend on each other's state, and the suite stays fast enough that people actually run it.", anchor: "Barclays R2 Q3" },
    { track: "framework", type: "mcq", topic: "FRAMEWORK", question: "Describe a standard Git workflow for automation code.", options: ["Everyone commits straight to main", "Feature branches off main, small commits, push and open a pull request, code review + CI green as the merge gate, then delete the branch — same discipline as application code", "Email zip files of the framework", "One permanent personal branch per engineer, merged yearly"], answer: 1, explanation: "Name the flow you actually use: branch per JIRA ticket, PR into main (or develop in gitflow shops), review plus the pipeline passing as the gate. Bonus points: automation code reviews check for dead assertions and flaky patterns, not just style.", anchor: "Barclays R2 Q7" },
    { track: "framework", type: "written", topic: "FRAMEWORK", question: "What common challenges have you faced in automation, and how did you resolve them?", coach: "Pick 2-3 real ones: synchronization/flakiness, dynamic locators, test data, environment instability. For each: the symptom, the root cause, the fix, and what you standardized so it stayed fixed.", model: "The recurring ones: synchronization — intermittent failures that turned out to be timing; I standardized explicit waits in a base class and banned Thread.sleep in review. Dynamic locators — auto-generated ids breaking tests; I moved to stable attributes and relative XPath anchored on text or data-test attributes, and pushed developers to add test ids. Test data collisions in parallel runs — tests sharing accounts; I made each test create or reserve its own data. And environment flakiness — I separated 'app is down' from 'test failed' with a health check before the suite, so red means defect, not noise. The pattern in all of them: fix the class of problem in the framework, not the one test.", anchor: "Barclays R2 Q9" },
    { track: "selenium", type: "mcq", topic: "SELENIUM", question: "What is the correct syntax contrast between absolute and relative XPath?", options: ["Absolute: //input[@id='user']; Relative: /html/body/div/input", "Absolute: /html/body/div[2]/form/input[1] starting from the document root; Relative: //input[@id='user'] starting anywhere and anchored on an attribute", "Both start with a single slash", "Relative XPath cannot use attributes, only tag names"], answer: 1, explanation: "A single leading slash (/) means an absolute path from the root node, spelling out every ancestor by tag and position — brittle to any layout change. A double slash (//) means relative — search anywhere in the document, and anchoring on a stable attribute like //input[@id='user'] or //button[text()='Submit'] survives structural churn.", anchor: "Field test addition" },
    { track: "api", type: "mcq", topic: "API", question: "What is the actual difference between SoapUI and a REST API?", options: ["They are competing REST protocols", "They aren't the same kind of thing: REST (and SOAP) are API architectural styles/protocols; SoapUI is a testing tool that can send requests to both SOAP and REST endpoints", "SoapUI only works with JSON", "REST APIs require SoapUI to run"], answer: 1, explanation: "This question conflates a tool with a protocol, so name that first. SOAP is a strict XML-based protocol with a WSDL contract; REST is an architectural style over HTTP verbs, typically JSON. SoapUI (and its REST Assured/Postman equivalents) is a client tool for exercising either kind of API — despite the name, it isn't limited to SOAP.", anchor: "Field test addition" },
    { track: "selenium", type: "mcq", topic: "SELENIUM", question: "What are the standard ways to locate elements on the DOM in Selenium?", options: ["Only By.id and By.xpath exist", "The eight By strategies: id, name, className, tagName, linkText, partialLinkText, cssSelector, and xpath", "By coordinates only (x, y position)", "Selenium locates elements by screenshot comparison"], answer: 1, explanation: "WebDriver's By class exposes eight locator strategies. Preference order for stability and speed: id, name, cssSelector, then xpath when you need parent traversal or text matching; linkText/partialLinkText are narrow-purpose for anchor tags.", anchor: "Field test addition" },
    { track: "selenium", type: "written", topic: "SELENIUM", question: "What is the difference between findElement() and findElements()? What happens when no element is found, and how would you handle those cases in your framework?", coach: "State the return types and the no-match behavior for each, then name a concrete framework pattern for the empty/absent case.", model: "findElement returns a single WebElement and throws NoSuchElementException when nothing matches, so it's the right call when the element must exist for the test to proceed. findElements returns a List<WebElement> and simply returns an empty list when nothing matches — no exception. In my framework I use that difference deliberately: a helper like isElementPresent(By) calls findElements(locator).size() > 0 to check existence without throwing, which I use for optional banners, toasts, or conditional UI instead of wrapping findElement in try/catch for control flow.", anchor: "Field test addition" },
    { track: "java", type: "mcq", topic: "JAVA", question: "How does a HashMap work internally in Java — hashCode/equals, collisions, and resizing?", options: ["It stores entries in sorted array order and binary-searches for keys", "It hashes the key via hashCode() into a bucket index, uses equals() to disambiguate keys within a bucket (a linked list, or a red-black tree once a bucket passes 8 entries), and rehashes into a doubled-capacity table once size exceeds capacity * loadFactor (default 0.75)", "Every key gets its own array slot with no collisions possible", "It never resizes; the initial capacity is fixed for the life of the map"], answer: 1, explanation: "put()/get() compute hash(key.hashCode()) to pick a bucket. Two keys landing in the same bucket are a collision — HashMap chains them (linked list, treeified to a red-black tree in Java 8+ once a bucket hits 8 entries) and uses equals() to find the exact key. When size crosses capacity * loadFactor, HashMap doubles the table and rehashes every entry into the new bucket layout — the reason a poorly distributed hashCode() degrades a HashMap toward O(n) lookups.", anchor: "Field test addition" },
    { track: "framework", type: "mcq", topic: "FRAMEWORK", question: "How do you perform data-driven testing with Excel and Java?", options: ["Excel data cannot be read by Java, only CSV", "Use Apache POI (Workbook/Sheet/Row/Cell) to read or write .xlsx files, then feed each row into the test via a TestNG @DataProvider or a JUnit 5 @ParameterizedTest with a custom ArgumentsProvider", "Copy the Excel file's cell values into hard-coded Java arrays by hand", "Convert the spreadsheet to a screenshot and OCR it"], answer: 1, explanation: "Apache POI's XSSFWorkbook opens the .xlsx file, getSheet/getRow/getCell walks the grid, and each row typically becomes one Object[] of test inputs. TestNG's @DataProvider returns Object[][] built from that walk; JUnit 5 achieves the same with @ParameterizedTest plus a custom ArgumentsProvider or @MethodSource. Writing results back uses the same POI objects plus a FileOutputStream to save the workbook.", anchor: "Field test addition" },
    { track: "selenium", type: "mcq", topic: "SELENIUM", question: "How would you click an element that keeps becoming stale?", options: ["Catch StaleElementReferenceException and ignore it silently", "Re-locate the element immediately before the click (don't reuse an old WebElement reference), optionally wrapped in a small retry loop that catches StaleElementReferenceException and re-finds the element", "Restart the WebDriver session", "Switch to JavaScriptExecutor permanently to avoid the exception"], answer: 1, explanation: "Staleness means the DOM node behind your WebElement reference was replaced or removed. The fix is to never hold onto the reference across a DOM-changing action — re-locate right before interacting, and for elements known to refresh under you (AJAX re-renders, animations), wrap the click in a short retry loop that catches StaleElementReferenceException, re-finds the element, and retries once or twice before failing loudly.", anchor: "Field test addition" },
    { track: "selenium", type: "mcq", topic: "SELENIUM", question: "How do you handle a hidden scrollbar or infinite scroll in automation?", options: ["Selenium cannot interact with any element outside the visible viewport", "Use JavascriptExecutor to scroll the element or window into view (scrollIntoView, or scrollBy in a loop for infinite scroll), waiting after each scroll for new content to load and stopping when the page/element scroll height stops increasing", "Resize the browser window until everything fits on one screen", "Use Thread.sleep(60000) to let everything load before scrolling"], answer: 1, explanation: "For an element below the fold, ((JavascriptExecutor) driver).executeScript(\"arguments[0].scrollIntoView(true);\", element) brings it into view before interacting. For infinite scroll, loop: scroll to the bottom (or scrollBy a fixed amount), wait for new elements/height change, and stop when document.body.scrollHeight (or the container's scrollHeight) no longer grows between iterations — a plain fixed-count loop of sleeps is the wrong answer here too.", anchor: "Field test addition" },
    { track: "api", type: "mcq", topic: "API", question: "What do the five HTTP status-code families mean?", options: ["They are arbitrary; only the exact number matters", "1xx informational, 2xx success, 3xx redirection, 4xx client error (fix the request), 5xx server error (the service failed)", "1xx success, 2xx redirect, 3xx client error, 4xx server error, 5xx informational", "Only 2xx and 4xx exist in REST"], answer: 1, explanation: "The first digit tells you who owns the problem: 4xx means the caller sent something wrong (don't retry unchanged); 5xx means the server failed (retry may work). In test triage this is the first split — a 4xx from your test is often a test bug; a 5xx is almost always a product defect.", anchor: "Repo Module 9 / status-code family" },
    { track: "api", type: "mcq", topic: "API", question: "A request body is syntactically valid JSON but fails business validation (e.g. negative trade quantity). Which status fits best, and how does it differ from 400?", options: ["500, because the server rejected it", "422 Unprocessable Entity for semantically invalid input; 400 Bad Request for malformed syntax the server can't parse — many Spring APIs use 400 for both, but a 500 on bad input is always a defect", "404, because the trade doesn't exist yet", "204, because nothing was created"], answer: 1, explanation: "400 = the server couldn't parse or understand the request (broken JSON, wrong types). 422 = parsed fine, but the content violates business rules. Spring Boot's @Valid failures default to 400; teams often standardize on one. The test that matters: bad input must produce a 4xx with a field-level error body — never a 500 stack trace.", anchor: "Repo Module 9 / negative-path testing" },
    { track: "api", type: "mcq", topic: "API", question: "GET /api/trades/9999 for a nonexistent trade vs PATCH to an endpoint that only supports GET and POST — which statuses do you expect?", options: ["404 for both cases", "404 Not Found for the missing resource; 405 Method Not Allowed (with an Allow header listing supported methods) for the unsupported verb", "400 for both", "405 for the missing trade; 404 for the wrong verb"], answer: 1, explanation: "404 means the URI doesn't resolve to a resource. 405 means the URI exists but not for that HTTP method — Spring MVC returns it automatically when no handler mapping matches the verb, and the Allow response header should list what IS supported. Testing both distinguishes routing defects from data defects.", anchor: "Repo Module 9 / status-code family" },
    { track: "api", type: "mcq", topic: "API", question: "When would an API correctly return 409 Conflict, and why does it matter in trade-booking tests?", options: ["Whenever two users are logged in at once", "When the request conflicts with current resource state — e.g. booking a trade with an ID that already exists, or updating with a stale version/ETag in optimistic locking", "Only for database deadlocks", "409 is a deprecated code"], answer: 1, explanation: "409 is the duplicate-submission and concurrent-update code: replaying the same create (idempotency-key collision) or PUTting with an outdated version number should conflict, not silently overwrite. A good negative test posts the same trade twice and asserts the second attempt gets 409 — not a second 201 creating a duplicate booking.", anchor: "Repo Module 9 / idempotency talk track" },
    { track: "api", type: "mcq", topic: "API", question: "Your test suite starts receiving 429 responses from a rate-limited service. What does 429 mean and how should clients (and tests) react?", options: ["The server crashed; file a Sev-1", "429 Too Many Requests — the client exceeded a rate limit; honor the Retry-After header and back off (exponentially), and in tests either throttle, use a test-tier key, or assert the limiting behavior itself", "It means authentication expired; refresh the token", "Ignore it and retry immediately in a tight loop"], answer: 1, explanation: "429 is the throttling signal from API gateways and rate limiters. The Retry-After header says when to try again; hammering immediately makes it worse. Rate limiting is also testable behavior: send N+1 requests within the window and assert the N+1th gets 429 with the right headers, then that service resumes after the window.", anchor: "Field test addition / API gateway behavior" },
    { track: "api", type: "mcq", topic: "API", question: "How do you tell apart 500, 502, 503, and 504 when a microservice call fails behind a gateway?", options: ["They are interchangeable server errors", "500 = the service itself threw an unhandled error; 502 = the gateway got an invalid response from upstream; 503 = the service is temporarily unavailable/overloaded (often during deploys); 504 = the upstream didn't answer within the gateway's timeout", "502 means bad JSON in the request", "504 means the client's internet is down"], answer: 1, explanation: "In a gateway → service chain these localize the failure: 500 points at the service's own code (check its logs for the stack trace), 502/504 point at the hop between gateway and upstream (dead instance vs slow instance), and 503 is capacity or a deploy window — often retryable with backoff. Naming which log you'd check for each is the senior answer.", anchor: "Repo Module 9 / microservices talk track" },
    { track: "api", type: "mcq", topic: "API", question: "What is the difference between 301, 302, and 304?", options: ["All three redirect to a new URL", "301 = moved permanently (clients/caches update to the new URI), 302 = temporary redirect (keep using the original), 304 = Not Modified — not a redirect at all, but a cache validation reply to a conditional GET (If-None-Match/ETag) with no body", "304 permanently moves the resource", "301 is only used by browsers, never APIs"], answer: 1, explanation: "REST Assured follows redirects by default, which can mask them — use .redirects().follow(false) to assert the 3xx and Location header directly. 304 pairs with ETag/If-None-Match: the second conditional GET returning 304 with an empty body proves caching works, a real test for read-heavy reference-data endpoints.", anchor: "Field test addition / HTTP caching" },
    { track: "api", type: "mcq", topic: "SPRING BOOT", question: "How can Spring's dependency injection (@Autowired, @Component, @Configuration) improve an automation framework?", options: ["It cannot; Spring is only for production applications", "Framework components — config readers, DB connections, API clients — become Spring-managed beans injected where needed, replacing hand-rolled singletons and new-everywhere wiring; @Configuration classes centralize bean creation, and the container owns lifecycle and teardown", "It replaces the test runner entirely", "@Autowired only works inside controllers"], answer: 1, explanation: "Instead of every test class constructing its own config reader or API client, you annotate them @Component and @Autowired them in — one instance, consistent state, mockable boundaries. spring-boot-starter-test integrates this with JUnit via @SpringBootTest or a custom test context, and Cucumber via cucumber-spring.", anchor: "Spring SDET list 1.1", employers: ["luxoft"] },
    { track: "api", type: "mcq", topic: "SPRING BOOT", question: "How do Spring Boot profiles manage multi-environment test setups (dev/qa/staging)?", options: ["Copy the framework once per environment", "Per-profile property files (application-qa.properties, application-dev.properties) hold each environment's URLs and credentials; activate one at runtime with -Dspring.profiles.active=qa from Maven or a CI variable — same suite, zero code changes per environment", "Profiles only work with a database", "Edit application.properties by hand before each run"], answer: 1, explanation: "application.properties holds shared defaults; application-{profile}.properties overrides per environment. The CI pipeline passes the profile (mvn test -Dspring.profiles.active=qa), and @Value or @ConfigurationProperties beans pick up the right values. Secrets still come from the CI vault, not the committed property files.", anchor: "Spring SDET list 1.2", employers: ["luxoft"] },
    { track: "api", type: "mcq", topic: "SPRING BOOT", question: "Why is a plain @Component (singleton-scoped) WebDriver manager dangerous under parallel execution, and what is the fix?", options: ["Singletons are slower to create", "Singleton scope means every test thread shares ONE driver instance — parallel tests would fight over the same browser; fix it with a ThreadLocal inside the bean (or a custom thread scope), so the shared bean hands each thread its own driver", "Spring forbids WebDriver beans", "Use @Component twice to get two instances"], answer: 1, explanation: "Spring beans default to singleton scope: one instance per container, shared across all threads. Ten parallel tests would all drive one browser — races, wrong-window failures, chaos. The standard fix keeps the manager a singleton but stores the driver in a ThreadLocal<WebDriver> inside it (exactly what this repo's DriverManager does), or registers a custom SimpleThreadScope.", anchor: "Spring SDET list 1.3 / repo DriverManager", employers: ["luxoft"] },
    { track: "api", type: "mcq", topic: "SPRING BOOT", question: "How can Spring Boot Actuator endpoints help a test automation strategy?", options: ["Actuator runs the tests for you", "Hit /actuator/health for each microservice as a pre-suite gate — if a dependency is DOWN, abort or mark the run as environment-failure instead of burning an hour producing false-negative regression failures; /metrics and /info add resource stats and deployed-version verification", "Actuator is only for production monitoring", "Actuator replaces JMeter"], answer: 1, explanation: "A @BeforeSuite health check turns 'the environment was down' from 200 red tests into one clear skip reason — red stays trustworthy. /info confirms you're testing the build you think you are; /metrics can watch memory/connections during a soak. This is the 'separate app-down from test-failed' pattern with an official endpoint.", anchor: "Spring SDET list 1.4", employers: ["luxoft"] },
    { track: "api", type: "mcq", topic: "API", question: "Developers added new fields to an API response and your tests now throw UnrecognizedPropertyException. What is the right design fix?", options: ["Freeze the API so it can never change", "Configure the mapper to tolerate additive change: @JsonIgnoreProperties(ignoreUnknown = true) on the POJO, or objectMapper.configure(FAIL_ON_UNKNOWN_PROPERTIES, false) globally — new fields shouldn't break consumers; pair with a contract/schema test that catches REMOVED or renamed fields, which are real breaks", "Catch and swallow the exception in every test", "Parse everything as raw strings instead"], answer: 1, explanation: "Additive fields are backward-compatible; tests that fail on them create noise and erode trust. Tolerate unknowns at the deserialization layer, then let a schema or contract test own the real compatibility question: removed/renamed/retyped fields. Know both halves — tolerance alone would silently miss genuine breaks.", anchor: "Spring SDET list 2.2" },
    { track: "api", type: "mcq", topic: "API", question: "How do you deserialize deeply nested JSON with dynamic arrays or fields whose type varies?", options: ["Deep nesting cannot be mapped to Java", "Mirror the nesting with composed POJOs (List<Position> inside Portfolio); for genuinely dynamic parts use JsonNode or Map<String, Object> for that subtree, @JsonAnySetter for catch-all fields, or a custom JsonDeserializer when one field arrives as string-or-number", "Flatten the JSON with regex first", "Always deserialize the whole response to a single String field"], answer: 1, explanation: "Structured-and-stable parts get typed POJOs — best assertions, best failure messages. Reserve JsonNode/Map escape hatches for the truly dynamic subtree only, so you don't give up type safety everywhere because one corner varies. Variable-type fields (e.g. an id as string or int) get a custom deserializer or the loosest safe type.", anchor: "Spring SDET list 2.1" },
    { track: "api", type: "mcq", topic: "API", question: "What is the difference between RequestSpecification and ResponseSpecification in REST Assured?", options: ["They are two names for the same object", "RequestSpecification bundles reusable request setup (base URI, auth token, headers, logging) built once with RequestSpecBuilder; ResponseSpecification bundles reusable response assertions (status family, content type, SLA) — given(requestSpec)...then().spec(responseSpec) keeps hundreds of tests DRY", "ResponseSpecification sends the request", "Specifications only work with XML"], answer: 1, explanation: "A base-test builder creates one RequestSpecification per service (URI, Authorization header, content type, .log().ifValidationFails()) and common ResponseSpecifications (e.g. 'any 2xx, JSON, under 2s'). Tests then add only what's unique to them. This is the API-side equivalent of BasePage — say that parallel out loud.", anchor: "Spring SDET list 2.3" },
    { track: "api", type: "written", topic: "API", question: "In a data-driven API suite, how do you dynamically mutate request payloads — POJO builders, a JSON template utility, or external JSON files? Defend your choice.", coach: "Name all three options with a pro and con each, then commit to a default and the exception cases.", model: "My default is the POJO builder pattern: a valid baseline object with fluent overrides — TradeRequest.builder().quantity(-5).build() — because it is type-safe, refactors with the contract, and each test states only what it changes. Its cost is upfront modeling. A Map or JSON-template utility is looser — good for deliberately malformed payloads a typed POJO cannot express, like a wrong-type field or missing required key. External JSON files keep huge realistic payloads readable, but they rot silently when the contract changes and hide what a test actually varies. So: builders for the data-driven matrix, template tampering for negative contract tests, files only for large golden payloads.", anchor: "Spring SDET list 2.4" },
    { track: "framework", type: "mcq", topic: "FRAMEWORK", question: "In Selenium 4, PageFactory @FindBy vs plain By locators with explicit waits — what is the practical trade-off?", options: ["PageFactory is required in Selenium 4", "PageFactory lazy-proxies @FindBy fields, but hides lookup timing and doesn't integrate with explicit-wait conditions cleanly; plain By constants passed into WebDriverWait conditions make synchronization explicit — the more robust default for AJAX-heavy SPAs", "By locators cannot be reused", "PageFactory was removed from Selenium 4"], answer: 1, explanation: "PageFactory still works, but the proxy re-finds the element on each access at an uncontrolled moment — awkward with SPA re-renders, and stale-prone with cached elements. By constants + until(elementToBeClickable(BY)) put the wait condition at the interaction point. For SPA robustness, add stable data-test attributes and anchor locators on them.", anchor: "Spring SDET list 3.1 / repo BasePage" },
    { track: "framework", type: "mcq", topic: "CUCUMBER", question: "How do you share state (like an order ID from a Given step) across Cucumber step-definition classes without global statics?", options: ["A public static String in a Utils class", "Constructor-inject a shared scenario-scoped context object via Cucumber's DI (PicoContainer, or cucumber-spring with @ScenarioScope) — each scenario gets a fresh instance, so parallel scenarios can't leak state into each other", "Write the value to a file between steps", "Merge all steps into one giant class"], answer: 1, explanation: "Static variables are the anti-pattern: shared across every parallel scenario, they cause cross-test leakage. Cucumber's DI creates one context instance per scenario and injects it into every step class that declares it in its constructor — PicoContainer needs just a dependency; cucumber-spring adds @ScenarioScope beans if the framework is already Spring-based.", anchor: "Spring SDET list 3.3" },
    { track: "framework", type: "mcq", topic: "CUCUMBER", question: "A stakeholder hands you a feature file that reads like a click-by-click manual (imperative Gherkin). What is the fix?", options: ["Run it as-is; more steps means more coverage", "Refactor to declarative: steps state business intent ('When the customer books a valid equity trade'), and the click mechanics move into step definitions and page objects — the feature survives UI changes and stays readable to the business", "Delete the scenario", "Convert every step to a Scenario Outline"], answer: 1, explanation: "'Given I click the username field / And I type john / And I click...' breaks on every UI tweak and buries intent. Declarative Gherkin is the executable specification; imperative detail belongs in code. Related tools: Scenario Outline + Examples for the same flow with many datasets; a data table to feed one step structured input — neither fixes imperativeness by itself.", anchor: "Spring SDET list 3.4 / repo Module 8" },
    { track: "framework", type: "mcq", topic: "CI/CD", question: "How should pipeline stages separate fast PR checks from heavy regression?", options: ["Run the full regression on every commit and accept slow PRs", "Layered gates: PR triggers fast smoke/sanity (minutes — critical paths, mostly API-level) as the merge gate; the full UI regression runs nightly or post-merge on a schedule; deep suites (cross-browser, performance) run on their own cadence — feedback speed where change happens, depth where time allows", "Only run tests manually before releases", "Nightly builds should run the smoke suite only"], answer: 1, explanation: "The shift-left principle: the cheapest, fastest checks sit closest to the developer's change. A PR gate over ~15 minutes gets bypassed culturally. In GitHub Actions/Jenkins this is separate workflows/stages with different triggers (pull_request vs schedule), sharing the same suite sliced by tags or groups.", anchor: "Spring SDET list 4.2" },
    { track: "interview", type: "written", topic: "VOICE", question: "How do you communicate the ROI of an automation framework to leadership, and which metrics do you monitor?", coach: "Pick metrics that map to money and risk, not vanity counts. Name 3-4, say what each proves, and name the one trap metric.", model: "I translate framework health into risk and time. Defect escape rate — bugs found in production versus before release — is the honest measure of whether automation catches what matters. Execution velocity — regression in hours instead of days — converts directly to release cadence and engineer time saved. Flake ratio and time-to-signal show whether the team can trust and act on a red build; a suite nobody trusts has negative ROI. I avoid the trap metric — raw test count — because a thousand shallow tests can be worth less than fifty that guard revenue paths. For leadership I frame it as: what used to take three days of manual regression now takes forty minutes per merge, and here is the escape-rate trend since.", anchor: "Spring SDET list 4.4" },
    { track: "api", type: "mcq", topic: "API", question: "A calculation API returns a huge nested JSON array whose item ORDER is unpredictable. Which validation toolset fits?", options: ["String-compare the response to a saved golden file", "Layered: POJO deserialization for typed business assertions and recomputation; JSONAssert in LENIENT mode (or a sort-then-compare on a stable key) for order-independent structural comparison; JSON Schema validation for types/required fields at scale", "Assert only the array length", "Unordered arrays cannot be validated"], answer: 1, explanation: "Each tool owns a layer: schema validation catches shape/type drift cheaply across the whole payload; JSONAssert LENIENT ignores ordering and extra fields (STRICT does neither); POJOs enable the assertions that matter — recomputing each item's math. For unordered arrays, either compare as sets keyed on a business ID or sort both sides by that key before comparing. Golden-file string comparison breaks on field order, whitespace, and every additive change.", anchor: "Financial JD list 1.2" },
    { track: "framework", type: "mcq", topic: "CUCUMBER", question: "How do you feed a large matrix of calculation permutations (inputs × rates × rounding cases) into a Cucumber framework?", options: ["Write one hand-typed scenario per permutation", "Scenario Outline + Examples for the readable business-facing cases; for big numeric matrices, keep Gherkin declarative ('for each case in the pricing matrix') and load the CSV/Excel vectors inside the step definition, asserting all rows with soft-assert-style collection so one failure doesn't hide the rest", "Cucumber cannot do data-driven testing", "Paste the spreadsheet into the feature file as a 500-row Examples table"], answer: 1, explanation: "Examples tables are for cases a stakeholder should read — a 500-row table makes the feature unreadable and slow to maintain. The pattern: the scenario names the matrix, the step loads the external vectors (POI for Excel, or CSV), runs every permutation, and reports ALL mismatches with row identifiers. Expected values come from the spec or a reference implementation, never from the code under test.", anchor: "Financial JD list 1.3" },
    { track: "framework", type: "mcq", topic: "FRAMEWORK", question: "An end-to-end scenario spans a Windows desktop UI and a microservices backend. How do you automate the transition?", options: ["Selenium WebDriver drives Windows apps natively", "Use a Windows UI driver (WinAppDriver speaks the WebDriver protocol; FlaUI wraps UI Automation) for the desktop steps, then assert the backend effect in the SAME scenario via REST Assured/SQL — the shared scenario context carries the transaction ID from UI step to API step", "Screenshot the app and compare pixels", "Test the UI and backend in separate suites that never share data"], answer: 1, explanation: "Selenium only drives browsers; desktop needs UI Automation-based tools — WinAppDriver conveniently reuses WebDriver-style code. The E2E value is the handoff: the UI step books the trade and stores its ID in the injected scenario context; the next steps poll the API for the resulting event and reconcile the database rows. Keep desktop-UI steps thin — they're the slowest, flakiest layer.", anchor: "Financial JD list 2.3" },
    { track: "testng-sql", type: "mcq", topic: "SQL", question: "How do you verify an API calculation correctly mutated rows across MULTIPLE database tables?", options: ["Check the API's 200 status; the DB is implied", "Capture pre-state, trigger the API, then query every affected table (e.g. via Spring's JdbcTemplate) and assert the full consistency picture: the trade row, the balance delta on accounts, the audit/ledger entry — and that debits equal credits", "Count total rows in the database before and after", "Trust the ORM to keep tables consistent"], answer: 1, explanation: "Financial consistency is cross-table by definition: one booking should atomically touch trades, positions/balances, and the audit trail. JdbcTemplate.queryForObject/queryForList keeps the SQL steps clean in Java. The senior additions: assert the delta from captured pre-state (not absolute values), verify the invariant (sums balance), and test the failure path — a rejected API call must leave NO partial writes.", anchor: "Financial JD list 3.2" },
    { track: "api", type: "mcq", topic: "PERFORMANCE", question: "How do you determine JMeter thread count and ramp-up, and what distinguishes a load test from a stress/spike test?", options: ["Always use 1000 threads immediately", "Derive load from production reality: peak concurrent users/request rate from analytics + SLA targets → thread count and pacing; ramp up gradually so the system warms realistically. Load = expected peak vs SLA; stress = keep increasing to find the breaking point; spike = sudden burst (e.g. market open) to test surge recovery", "Thread count is always CPU cores × 2", "Ramp-up time only affects the report formatting"], answer: 1, explanation: "The numbers come from a workload model, not guesswork: requests/sec at peak, converted through pacing into threads. Load testing answers 'does it meet the SLA at expected peak'; stress finds the ceiling and the failure mode (graceful degradation vs collapse); spike matters for financial apps because market-open bursts are the real profile — instant surge, then does it recover?", anchor: "Financial JD list 4.1" },
    { track: "api", type: "mcq", topic: "PERFORMANCE", question: "Why must every JMeter thread send UNIQUE calculation inputs, and how do you achieve it?", options: ["Duplicate data crashes JMeter", "Calculation engines cache repeated inputs, so identical payloads measure the cache, not the computation — parameterize with CSV Data Set Config (unique vectors per thread, sharing mode set correctly), plus functions like __Random/__counter/__UUID for generated fields", "Unique data is only needed for database tests", "Use the same payload but change the User-Agent header"], answer: 1, explanation: "Hitting a cached path under-reports latency drastically — the classic way a service 'passes' load testing and then falls over in production. CSV Data Set Config feeds each thread different rows (mind the sharing mode: all-threads vs per-thread), and __UUID/__counter make IDs collision-free. Sanity-check it worked: if p95 looks impossibly flat and fast, you probably measured the cache.", anchor: "Financial JD list 4.2" },
    { track: "api", type: "written", topic: "PERFORMANCE", question: "Your JMeter run shows response times spiking sharply at 50 concurrent users. Walk through your troubleshooting process.", coach: "Show a correlation method, not a tool list: client-side metrics first, then server-side, then the usual suspects for a hard knee in the curve.", model: "First I confirm the measurement: is the spike real on the server or a JMeter artifact — is the load generator itself CPU-bound? Then I read the client-side shape: throughput flat while latency climbs means requests are queuing; error rate and which errors — timeouts point at exhaustion, 5xx at faults. A sharp knee at a specific concurrency usually means a fixed resource ran out, so I correlate the timestamp against server metrics: CPU and memory, GC pauses, and the classic culprits — thread pool size, database connection pool, rate limiter — many defaults sit near 50. Then application logs and traces for where time is actually spent, database slow queries under concurrent load, and locking on shared calculation state. I report it as: the system saturates at N users, here is the limiting resource, here is the evidence.", anchor: "Financial JD list 4.3" },
    { track: "api", type: "mcq", topic: "API", question: "A POST returns 202 Accepted and a job ID. How should an automated test wait for the final calculation result?", options: ["Sleep for a fixed 60 seconds, then check once", "Poll the status endpoint with a bounded timeout and controlled interval/backoff, stop on a terminal state, and fail with the last observed state and correlation ID", "Immediately expect the final result in the 202 response", "Retry the POST until it returns 200"], answer: 1, explanation: "A 202 response means processing has started, not finished. Poll a documented status or result URI until SUCCESS or FAILED, with a total timeout and sensible interval/backoff. Do not repeat a non-idempotent POST or use an unbounded loop. Include the job/correlation ID and last response in the failure so the service can be traced.", anchor: "Luxoft JD: microservices + calculation-intensive flows / async API gap" },
    { track: "api", type: "mcq", topic: "MICROSERVICES", question: "How would you verify timeout, retry, and circuit-breaker behavior when a Spring Boot service calls a slow downstream service?", options: ["Wait for the shared test environment to fail naturally", "Use WireMock to inject delays/errors, assert the public response and latency budget, verify the bounded retry count, and confirm no duplicate side effects; then verify the circuit opens and later recovers", "Mock the service under test so no production code runs", "Increase every timeout until the test passes"], answer: 1, explanation: "A programmable HTTP stub makes failure modes deterministic. Test one slow/erroring dependency at a time, verify retries are bounded and safe, confirm the caller returns the agreed fallback or error, and prove a retried trade request does not create duplicate writes. Circuit-breaker tests should also cover half-open recovery.", anchor: "WireMock official fault simulation / Luxoft microservices responsibility — runnable: drills/d11_resilience/SourceD11ResilienceDrills.java", employers: ["luxoft"] },
    { track: "api", type: "mcq", topic: "SPRING BOOT", question: "Which Spring Boot test layer should you choose for a controller, repository, full service, and deployed API?", options: ["Use @SpringBootTest for every test", "@WebMvcTest + MockMvc for the controller slice; @DataJpaTest for repositories; @SpringBootTest with RANDOM_PORT for the full application; REST Assured for black-box tests against a deployed service", "Use Selenium for all four layers", "Use @DataJpaTest for controllers and @WebMvcTest for SQL"], answer: 1, explanation: "Choose the narrowest layer that proves the risk. Slice tests are fast and local, RANDOM_PORT proves application wiring over real HTTP, and black-box REST Assured proves the deployed contract. A small number of Testcontainers-backed integration tests can cover real database behavior when an embedded database would hide vendor differences.", anchor: "Spring Boot official testing reference / repo Module 9", employers: ["luxoft"] },
    { track: "framework", type: "written", topic: "TEST DESIGN", question: "A business analyst gives you a new calculation rule. How do you turn it into comprehensive test scenarios before automating it?", coach: "Show test-design technique and financial judgment: clarify the rule, identify inputs and invariants, partition the space, cover boundaries and states, choose an independent oracle, and prioritize by risk.", model: "I first restate the rule with concrete examples and resolve ambiguity with the analyst, especially rounding, currency, effective dates, and invalid states. I map inputs, outputs, dependencies, and invariants such as totals balancing. Then I use equivalence partitions and boundary values for numeric ranges, a decision table for combinations of status/rate/currency, and state transitions for the trade lifecycle. Expected values come from the specification or an independent reference calculation, not the same production algorithm. I include happy, negative, null, duplicate, precision, authorization, and downstream-failure cases, then automate the stable high-risk matrix mostly at API level with a thin end-to-end path.", anchor: "Luxoft JD: analyze requirements and create comprehensive scenarios" },
    { track: "framework", type: "written", topic: "CODE REVIEW", question: "You are reviewing a Java/Cucumber/REST Assured automation pull request. What do you inspect before approving it?", coach: "Cover correctness first, then reliability, design, diagnostics, data isolation, security, and CI cost. Mention the planted-bug check: captured values that are never asserted.", model: "I start with whether the test proves the requirement: expected values must come from a reliable oracle, and every captured response value must reach an assertion. Then I check negative and boundary coverage, status/header/body assertions, BigDecimal use for money, and cleanup or unique data so the test is repeatable and parallel-safe. I look for sleeps, broad retries, static shared state, duplicated request setup, brittle Gherkin, swallowed exceptions, secrets in code, and logging that leaks tokens. Finally I check failure diagnostics, naming, focused scope, and whether the test belongs in the PR gate or a slower scheduled suite. I run the changed tests and leave comments tied to risk, not personal style.", anchor: "Luxoft JD: code reviews + Bitbucket / senior QA responsibility" },
    { track: "api", type: "written", topic: "SECURITY", question: "What security and audit scenarios would you test for an investment-banking API?", coach: "Go beyond missing-token checks: authentication, authorization, object-level access, sensitive data, input handling, auditability, and replay/duplicate protection.", model: "I test missing, expired, malformed, and tampered tokens for 401, then valid users with the wrong role or scope for 403. I verify object-level authorization so one desk or account cannot access another by changing an ID, and I check sensitive fields are masked and never exposed in errors or logs. Inputs get boundary and injection tests, transport must be TLS, and create operations need idempotency or duplicate-booking protection. For every material trade action I verify an immutable audit event records who, what, when, correlation ID, and outcome without storing secrets. I also prove denied and failed requests do not leave partial database writes.", anchor: "Spring Security official testing guidance / investment-banking risk" },
    { track: "interview", type: "written", topic: "LEADERSHIP", question: "You're the Test Lead for one workstream inside a large-scale, multi-team implementation program. Walk through how you build the test plan.", coach: "Cover requirements analysis, estimation, strategy, data planning, and how your plan interlocks with the Program Test Manager's schedule — this is the JD's exact language, use it.", model: "I start by decomposing the requirements for my workstream into testable scenarios and flag anything ambiguous or untestable back to the analysts before estimation, not after. Estimation is bottom-up from scenario count and complexity, cross-checked against past cycles, with explicit buffer for environment and data readiness risk — I never hand up a single number without the assumptions behind it. The test strategy names what's automated versus manual, which layers carry the coverage (API and data validation first, UI for critical paths), and what data and environment dependencies exist, including any interface partners. I build the plan in the Program Test Manager's format so my workstream rolls up cleanly into the master schedule, and I track planned-versus-actual weekly so schedule risk surfaces early rather than at the exit gate.", anchor: "Lead QA JD field test — own test planning" },
    { track: "interview", type: "mcq", topic: "ESTIMATION", question: "A Program Test Manager asks for a test-effort estimate before requirements are fully finalized. What is the strongest approach?", options: ["Refuse to estimate until requirements freeze", "Give a single fixed number and hold to it regardless of scope changes", "Estimate against the current requirement set using a repeatable method (scenario count/complexity or past-cycle actuals), state assumptions and known unknowns explicitly, and commit to re-baselining the estimate as requirements firm up", "Copy the estimate from a similar project without adjustment"], answer: 2, explanation: "Estimates made under requirement volatility are only useful if the assumptions are visible and the number is explicitly a moving target. A Test Lead's job is to make the uncertainty legible — not to pretend precision that doesn't exist, and not to stonewall the ask.", anchor: "Lead QA JD field test — test planning and estimation", employers: ["builders-mutual"] },
    { track: "interview", type: "written", topic: "DEFECT MGMT", question: "Describe how you run defect triage as the Test Lead across developers, BAs, and the Program Test Manager.", coach: "Name the cadence, who owns which decision, how root cause analysis fits in, and how you keep triage from becoming a status meeting.", model: "I run a standing triage cadence — daily during active test cycles — with a fixed agenda: new defects get severity and priority assigned first using evidence, not opinion, then owners and target resolution are agreed in the room, not after. I push for root cause, not just symptom-fix, especially on repeat-pattern defects, because the same root cause showing up across three tickets is a signal worth escalating on its own. I keep a running defect-trend view — open by severity, aging, and reopen rate — so the conversation stays about risk trending up or down rather than re-litigating each ticket. Anything blocked past its target date I escalate to the Program Test Manager with the business impact stated plainly, not just the ticket number.", anchor: "Lead QA JD field test — defect management, triage leadership, RCA", employers: ["builders-mutual"] },
    { track: "interview", type: "mcq", topic: "RISK", question: "Two weeks before a planned go-live, your workstream has a cluster of interface defects with the same root cause, and the fix depends on an external integration partner. What is the right escalation move?", options: ["Keep working the defects and mention it at the next scheduled status meeting", "Immediately escalate to Program Test Management with the risk, business impact, dependency on the external partner, and options (delay, scope cut, mitigate), then keep driving it to closure", "Close the defects as \"won't fix\" to keep the metrics clean", "Wait for the integration partner to reach out first"], answer: 1, explanation: "A shared root cause plus an external dependency is exactly the risk profile that needs proactive escalation with options attached, not passive status reporting. The Test Lead's job is end-to-end follow-through on risks and dependencies, not just visibility.", anchor: "Lead QA JD field test — risk, issue, and dependency escalation" },
    { track: "interview", type: "mcq", topic: "AUTOMATION STRATEGY", question: "As the Test Lead defining automation strategy for a large regression suite across a program, what should drive the roadmap?", options: ["Automate whatever the most enthusiastic engineer wants to build first", "Prioritize by regression risk and execution frequency, choose the layer (API/data first, UI for critical journeys), and sequence the roadmap against the program's release cadence so automation coverage lands ahead of when it's needed", "Automate 100% of manual test cases before any release", "Delay all automation until the application is feature-complete"], answer: 1, explanation: "Automation strategy at program scale is a portfolio decision: risk-weighted coverage, the cheapest reliable layer, and timing it against the release calendar — not a backlog of interesting technical problems.", anchor: "Lead QA JD field test — define and drive automation strategy" },
    { track: "interview", type: "written", topic: "AI TESTING", question: "The JD asks you to leverage AI for testing activities to increase efficiency. What does that actually look like day to day?", coach: "Be concrete and honest about where AI helps and where it doesn't — this should sound like lived experience, not a buzzword answer.", model: "Concretely: I use Claude Code and GitHub Copilot to draft new Selenium/Java test scaffolding and Page Object boilerplate from a description of the flow, which cut my test-creation time meaningfully and let me spend more time on assertion quality and edge cases instead of typing structure. I also use AI to summarize defect clusters and surface likely root-cause patterns across a large open-defect list before a triage session, and to draft first-pass test cases from requirements text that I then review and tighten rather than accept as-is. The boundary I hold is that AI output is a draft, not a decision — I still review generated locators and assertions for correctness, and I don't let it choose severity/priority or make the ship/no-ship call. It's a force multiplier for volume and first drafts, not a replacement for test judgment.", anchor: "Lead QA JD field test — leverage AI for testing activities" },
    { track: "testng-sql", type: "mcq", topic: "ETL", question: "What does ETL testing verify that ordinary API or UI testing does not?", options: ["Nothing different; ETL testing is identical to functional testing", "That data is correctly extracted from source systems, transformed per business rules (mappings, aggregations, type conversions), and loaded into the target without loss, duplication, or truncation — validated by comparing source and target directly, usually with SQL", "Only that the ETL job completes without throwing an exception", "That the UI displays the data quickly"], answer: 1, explanation: "ETL testing is a data-correctness discipline: row counts reconcile between source and target, transformation rules are verified with representative and boundary values, and referential integrity and data types survive the load. A green job log proves nothing about whether the data is right.", anchor: "Lead QA JD field test — advanced SQL for ETL testing" },
    { track: "testng-sql", type: "mcq", topic: "ETL", question: "How do you validate a nightly ETL load moved the correct row counts and values from source to target?", options: ["Trust the job's success/failure status in the scheduler", "Run reconciliation SQL against both systems: compare row counts, key-level checksums or hash totals on business columns, and spot-check transformed fields against the mapping document; investigate any delta before signing off", "Manually open both tables in a GUI and eyeball a few rows", "Only check that the target table is not empty"], answer: 1, explanation: "Row-count parity is the first, weakest check. The real validation is a checksum or aggregate comparison (SUM/COUNT/hash) on business-meaningful columns between source and target, plus targeted checks against the transformation mapping — nulls introduced, truncated strings, or a currency conversion applied incorrectly are the defects that count-only checks miss.", anchor: "Lead QA JD field test — ETL testing, source-to-target validation" },
    { track: "framework", type: "mcq", topic: "AWS", question: "Which AWS services are most relevant to supporting test execution in a hybrid or cloud environment, from a QA (not admin) perspective?", options: ["Route 53 and CloudFront only", "EC2/ECS or containers for running test grids at scale, S3 for storing test artifacts and reports, CloudWatch for logs and metrics during a run, and Secrets Manager/Parameter Store for credentials instead of hard-coded values", "Only RDS matters for testing", "AWS has no relevance to test execution"], answer: 1, explanation: "A QA lead doesn't need to administer AWS, but should recognize the pieces that show up in a test pipeline: compute to scale execution (EC2/ECS/Fargate, or a Selenium Grid on it), S3 for artifact/report storage, CloudWatch for run and application logs, and Secrets Manager/Parameter Store so credentials never live in a repo or property file.", anchor: "Lead QA JD field test — AWS fundamentals for test execution" },
    { track: "framework", type: "mcq", topic: "AWS", question: "Your CI pipeline needs to pull a database credential to run data-validation tests, and it currently sits in a checked-in properties file. What's the AWS-appropriate fix?", options: ["Leave it, since the repo is private", "Move it to AWS Secrets Manager or Parameter Store, have the pipeline fetch it at runtime with an IAM role scoped to only that secret, and rotate it — never commit credentials to source control", "Base64-encode it in the same file", "Email it to the team instead of committing it"], answer: 1, explanation: "Base64 is encoding, not security — it's trivially reversible. The standard fix is a managed secrets store with scoped IAM access and rotation, fetched at runtime by the CI job. This is also a defect worth filing if you find it during a security-adjacent review.", anchor: "Lead QA JD field test — AWS fundamentals, credential handling" },
    { track: "framework", type: "mcq", topic: "UNIX", question: "You need to confirm a specific service is running and check its recent errors on a Linux test environment before kicking off a regression cycle. Which commands do that?", options: ["dir and type", "ps -ef | grep <service> (or systemctl status <service>) to confirm it's running, and tail -f /var/log/<service>.log or grep ERROR <logfile> to check recent errors", "cd and ls only", "A GUI is required; there is no command-line way to check this"], answer: 1, explanation: "This is the pre-flight health check a Test Lead should be comfortable doing directly: process/service status, then a targeted log read. Doing this yourself instead of filing a ticket and waiting is often the difference between catching an environment issue in five minutes versus burning an hour on false-negative test failures.", anchor: "Lead QA JD field test — Unix/Linux command-line operations" },
    { track: "framework", type: "mcq", topic: "UNIX", question: "What's a practical use of basic shell scripting in a QA/test-lead role, beyond running the test suite itself?", options: ["Shell scripts are only for system administrators, not QA", "Small scripts to archive/clean old test-result and log directories, grep failure patterns out of a large log for a triage summary, or chain a health-check + test-run + report-copy sequence for a repeatable pipeline step", "Writing the entire test framework in bash instead of Java", "Shell scripting has no place in a Selenium/Java project"], answer: 1, explanation: "The bar is basic scripting fluency, not a rewrite of the framework: a short script that greps yesterday's failures into a one-page triage summary, or rotates old artifacts so a CI disk doesn't fill up, is exactly the kind of Unix/Linux comfort the JD is asking about.", anchor: "Lead QA JD field test — Unix/Linux basic scripting" },
    { track: "interview", type: "written", topic: "VOICE", question: "How do you run a stakeholder walkthrough or demo of test results so it builds confidence instead of just delivering numbers?", coach: "Contrast a numbers-dump demo with one that tells the risk story — what's covered, what's not, what's trending, and what decision you need from the room.", model: "I lead with the decision the room needs to make, not the raw metrics — are we on track for the exit gate, yes or no, and what would change that. I show planned-versus-actual execution and open-defect trend by severity so people see direction, not just a snapshot, and I call out the two or three scenarios that matter most to the business rather than walking every test case. For UAT and production-adjacent demos I show the actual business-critical scenario running, not just a green summary line, because stakeholders trust what they watch work. I close by naming what's still open, who owns it, and by when — so the walkthrough ends in an action list, not just applause or silence.", anchor: "Lead QA JD field test — walkthroughs, demos, UAT support" },
    { track: "interview", type: "mcq", topic: "PROCESS", question: "In a healthcare or other regulated-industry implementation, what does the Test Lead need to add on top of standard system testing?", options: ["Nothing changes; regulated industries test exactly like any other industry", "Traceability from requirement to test case to defect (often required for audit), attention to PHI/PII data handling in test environments (masked or synthetic data), and evidence retention that satisfies compliance review — not just a pass/fail result", "Only faster test cycles, since compliance doesn't affect testing", "Skip negative testing to save time since the schedule is already tight"], answer: 1, explanation: "Regulated environments (healthcare, financial services) usually require an auditable chain — which requirement each test covers, evidence of execution, and defect disposition — plus real discipline about not using live PHI/PII in lower environments. This is table stakes experience the JD explicitly prefers.", anchor: "Lead QA JD field test — healthcare/regulated industry experience" },
    { track: "api", type: "mcq", topic: "API", question: "Your workstream depends on an interface with an external integration partner, and their test data isn't ready for your scheduled cycle. As Test Lead, what's the right sequence of actions?", options: ["Skip interface testing for this cycle and mark it complete", "Confirm the dependency and its impact on your schedule, escalate the data-readiness gap to Program Test Management and the partner team with a target date, and in parallel stand up a stub/mock of the interface so non-dependent testing can continue", "Wait silently until the partner team responds on their own timeline", "Test against production data from the partner system to work around the gap"], answer: 1, explanation: "Coordinating with external partners for interface testing and data readiness is explicitly the Test Lead's job — that means naming the dependency and its schedule impact loudly, escalating with a target, and unblocking your own team with a stub in the meantime rather than letting the whole cycle stall or reaching for risky workarounds like live data.", anchor: "Lead QA JD field test — coordinate with external partners for interface testing" },
    { track: "interview", type: "written", topic: "LEADERSHIP", question: "How do you mentor QA team members who need to grow into automation, data validation, or white/gray-box testing?", coach: "Name a concrete mechanism, not just \"I mentor them\" — pairing, code review standards, a graduated task ladder, and how you calibrate difficulty per person.", model: "I start from where each person actually is, not a generic curriculum — someone strong in manual testing but new to automation gets paired on a real page object or step definition, not a toy exercise, so the skill sticks to work that matters. I use code review as a teaching tool: comments explain the why, not just the fix, and I look for the same person needing the same correction only once or twice before it becomes their default. For data validation and white/gray-box work, I walk through one SQL reconciliation or one API-layer investigation together end to end before handing similar work over solo. I also create visible stretch opportunities — owning triage for a feature area, presenting a demo — because growth that never gets exercised in front of stakeholders doesn't really land.", anchor: "Lead QA JD field test — mentor and guide QA team members" },
    { track: "interview", type: "written", topic: "RISK", question: "How do you report testing status, defect trends, and quality indicators to Program Test Management so it's useful, not just a status update?", coach: "Distinguish a report that informs a decision from one that just recites numbers — name the specific indicators and what each one is meant to trigger.", model: "I report planned-versus-actual execution progress, open-defect count by severity with an aging view, and reopen rate, because each of those answers a different question — are we on schedule, is the product getting more or less stable, and is the fix quality holding up. I flag trend direction explicitly, not just the current snapshot, because a rising Sev-1 count with two days left in the cycle is a very different conversation than the same count trending down. Anything that could threaten the exit gate gets called out on its own, with the business impact and the options, rather than buried in a table the Program Test Manager has to parse to find the risk themselves. The goal of the report is that someone reading only the top three lines can still make the right call.", anchor: "Lead QA JD field test — transparent status reporting to Program Test Management", employers: ["builders-mutual"] },
    { track: "interview", type: "mcq", topic: "STRATEGY", question: "You have very limited time before a release. How do you prioritize testing?", options: ["Run the full regression suite anyway and slip the date", "Test whatever modules the team knows best", "Risk-based: cover changed code, critical business flows, and integration points first; drop low-risk, stable areas explicitly and tell stakeholders what was skipped", "Only run automated tests since they are fastest"], answer: 2, explanation: "Time-boxed testing is a prioritization exercise: rank by business impact × likelihood of failure. Changed areas and money-path flows go first. The senior move is making the skipped coverage visible — an explicit, communicated risk acceptance instead of a silent gap.", anchor: "Scenario bank Q2" },
    { track: "interview", type: "mcq", topic: "PROCESS", question: "Requirements are incomplete or ambiguous. What do you do before starting testing?", options: ["Wait until the BA finishes the document", "Test based on your own assumptions and log bugs against them", "Clarify with the BA/product owner, document assumptions where answers aren't available, write scenarios against acceptance criteria, and get them reviewed — ambiguity found in review is cheaper than in a defect fight", "Skip the feature until the next sprint"], answer: 2, explanation: "Blocking entirely wastes the sprint; testing on private assumptions creates 'works as designed' disputes. Drive clarification actively, record the assumptions you had to make, and use scenario review to force ambiguity into the open early.", anchor: "Scenario bank Q6", employers: ["builders-mutual"] },
    { track: "interview", type: "mcq", topic: "PROCESS", question: "Business requirements change in the middle of the sprint. How do you handle it?", options: ["Refuse the change until next sprint", "Quietly retest everything from scratch", "Assess impact on existing test cases and automation, update or retire affected cases, re-estimate remaining effort, and surface any schedule/scope trade-off to the team rather than absorbing it silently", "Log the change as a defect"], answer: 2, explanation: "Change is normal; the failure mode is absorbing it invisibly. Impact-analyze test assets, re-plan, and make the cost visible so scope, date, or coverage gets consciously traded — not discovered at the end.", anchor: "Scenario bank Q7", employers: ["builders-mutual"] },
    { track: "interview", type: "mcq", topic: "RISK", question: "How do you identify high-risk areas of an application?", options: ["Ask developers which parts they like least", "Assume the newest feature is always the riskiest", "Combine signals: defect history per module, code churn, complexity, dependency fan-out, usage frequency, and business impact of failure — risk lives where change meets criticality", "Run all tests and see what fails"], answer: 2, explanation: "Risk = likelihood × impact. Likelihood signals: past defect density, recent churn, complex or heavily-dependent modules. Impact signals: revenue paths, compliance, data integrity. The intersection drives test depth and automation priority.", anchor: "Scenario bank Q8-9" },
    { track: "interview", type: "mcq", topic: "PROCESS", question: "A defect cannot be reproduced consistently. How do you investigate it?", options: ["Close it as non-reproducible after three tries", "Escalate it immediately to management", "Capture every variable at failure time — logs, screenshots, data state, environment, timing, browser — look for the pattern across occurrences (parallel runs, specific data, race conditions), and try to force the timing window rather than just re-running", "Wait for it to happen in production"], answer: 2, explanation: "Intermittent defects are usually timing, data, or environment dependent. Widen the evidence per occurrence, then difference the failing runs against passing ones. Deliberately amplifying suspected conditions (load, latency, parallelism) turns 'sometimes' into 'reliably' — which is when it becomes fixable.", anchor: "Scenario bank Q13" },
    { track: "interview", type: "mcq", topic: "PROCESS", question: "Multiple teams are releasing changes into the same environment simultaneously. How do you coordinate testing?", options: ["Each team tests independently and hopes for the best", "A shared release calendar and change manifest, integration testing after all merges land, clear environment ownership windows, and one cross-team triage channel for defects that span components", "Only one team is allowed to release per month", "Skip integration testing to save time"], answer: 1, explanation: "The risk in simultaneous releases is the interaction between changes, which no single team's suite covers. Coordination artifacts (calendar, manifest, ownership windows) plus a dedicated integration pass and shared triage keep cross-team defects from bouncing between backlogs.", anchor: "Scenario bank Q18" },
    { track: "interview", type: "mcq", topic: "RELEASE", question: "How do you decide whether a build is ready for release?", options: ["All tests passed, so ship it", "The developers say it's ready", "Check agreed exit criteria: planned tests executed, pass rate at threshold, no open Sev-1/Sev-2 defects (or explicit business sign-off on deferrals), regression green, and known-risk areas reviewed — readiness is a criteria decision, not a gut feeling", "Release on the planned date regardless"], answer: 2, explanation: "Define exit criteria before the cycle so the release call is objective. QA's job is to present the evidence against those criteria and the residual risk; the go/no-go is then a business decision made with eyes open, and deferred defects carry explicit sign-off.", anchor: "Scenario bank Q19" },
    { track: "interview", type: "mcq", topic: "RELEASE", question: "How do you measure release quality?", options: ["Number of test cases executed", "Defect escape rate to production, severity-weighted defect trends, test coverage of changed code, reopen rate, and post-release incident count — outcomes, not activity", "How fast the release went out", "Lines of automation code written"], answer: 1, explanation: "Executed-test counts measure effort, not quality. Escape rate answers the real question — what did the process miss — while reopen rate measures fix quality and post-release incidents measure customer impact. Track trends across releases, not single snapshots.", anchor: "Scenario bank Q20" },
    { track: "framework", type: "mcq", topic: "REGRESSION", question: "How do you decide what belongs in a regression suite?", options: ["Every test ever written", "Only the tests that failed recently", "Critical business flows, areas with defect history, integration points, and high-usage paths — tiered into smoke, targeted, and full regression so scope matches the change risk", "Whatever fits in one hour of execution"], answer: 2, explanation: "A regression suite is a risk portfolio, not an archive. Tier it: smoke for every build, targeted regression mapped to changed modules, full regression for releases. Prune tests that never fail and cover dead functionality — suite trust decays when it's bloated.", anchor: "Scenario bank Q16" },
    { track: "framework", type: "mcq", topic: "REGRESSION", question: "Regression execution time has become too long. How do you optimize it?", options: ["Delete half the tests alphabetically", "Buy faster laptops for the team", "Parallelize execution, push checks below the UI to the API layer, remove redundant/overlapping cases, use change-based selection for PRs with full runs nightly, and fix slow setup (login via API, seeded data instead of UI navigation)", "Run regression only once per release"], answer: 2, explanation: "Attack it on four fronts: run concurrently (ThreadLocal drivers, CI matrix), test at the cheapest layer that proves the behavior, cut duplication, and stop re-running everything for every change. UI login and data setup are usually the biggest hidden cost — replace them with API shortcuts.", anchor: "Scenario bank Q17/Q42" },
    { track: "api", type: "mcq", topic: "API", question: "How would you validate paginated API responses?", options: ["Check only the first page", "Verify page size and metadata (total count, page number, links), boundary pages (first, last, out-of-range, empty result set), no duplicate or missing records across consecutive pages, and stable ordering — plus behavior when data changes between page requests", "Request all pages and count them once", "Pagination is a UI concern, not an API one"], answer: 1, explanation: "The classic pagination bugs are records duplicated or dropped at page boundaries (usually an unstable sort) and wrong totals. Walk consecutive pages asserting the union is complete and disjoint, hit the edges (page 0, past-the-end, size=1, size>max), and verify a deterministic order-by underpins it.", anchor: "Scenario bank Q32" },
    { track: "api", type: "mcq", topic: "API", question: "How do you test APIs whose responses contain changing or dynamic values (IDs, timestamps, tokens)?", options: ["Assert the full response string exactly and update it every run", "Skip validating dynamic fields entirely", "Assert dynamic fields by contract — present, correct type/format (regex for UUIDs, ISO-8601 for timestamps), sane range — while asserting stable business fields exactly; or compare full payloads with dynamic paths explicitly ignored", "Mock the API so values never change"], answer: 2, explanation: "Exact-match assertions on dynamic data guarantee flakiness; ignoring the fields guarantees blind spots. Validate shape and format for generated values, exact values for business data. JSON-comparison libraries with ignored paths give full-payload coverage without the brittleness.", anchor: "Scenario bank Q33" },
    { track: "api", type: "mcq", topic: "API", question: "How would you validate eventual consistency in a distributed system?", options: ["Assert immediately after the write; if it fails, the system is broken", "Add a fixed 30-second sleep before every read", "Poll the read side with a timeout (awaitility-style) asserting convergence within the documented SLA, verify intermediate states are valid rather than corrupt, and test the failure path — what happens if the event is lost or delivered twice", "Eventual consistency cannot be tested"], answer: 2, explanation: "The contract isn't 'instantly consistent', it's 'converges within X'. So assert convergence-within-SLA by polling, not sleeping. The deeper tests are duplicate delivery (idempotency), out-of-order events, and lost messages — that's where distributed systems actually break.", anchor: "Scenario bank Q30" },
    { track: "testng-sql", type: "mcq", topic: "SQL", question: "How would you test a database migration without data loss?", options: ["Run the migration and spot-check a few rows", "Trust the migration script since it was code-reviewed", "Snapshot source counts and checksums per table first, run the migration on a production-like copy, then reconcile: row counts, aggregate checksums, null/constraint violations, sampled row-level field comparison, and application smoke tests against the migrated schema — with a tested rollback plan", "Only test the new schema's structure"], answer: 2, explanation: "Migration testing is a before/after reconciliation problem: counts and checksums catch bulk loss, row-level sampling catches transformation errors, constraint checks catch silent truncation or nulls. Rehearse on production-scale data — volume exposes timeouts and encoding issues a dev copy hides — and verify the rollback actually restores.", anchor: "Scenario bank Q38" },
    { track: "interview", type: "written", topic: "STRATEGY", question: "A major release is planned for a large application. How would you prepare the overall testing strategy?", coach: "Show a structure: scope and risk analysis first, then test levels, environments, data, automation vs manual split, entry/exit criteria, and schedule with milestones. Name who you align with.", model: "I start from scope and risk, not test cases — what changed, what it touches, and what hurts most if it breaks — usually with the BAs, architects, and product owner in the room. From that I define the levels: unit and API coverage expectations with dev, system and integration testing owned by QA, then UAT and a performance pass if the release changes load characteristics. I plan environments and test data early because they're the usual critical path, decide the automation-versus-manual split by repetition and stability, and set entry and exit criteria up front so the release decision is objective later. The strategy document ends with milestones, responsibilities, and the risks I'm explicitly not covering — a strategy that hides its gaps isn't a strategy.", anchor: "Scenario bank Q1" },
    { track: "interview", type: "written", topic: "STRATEGY", question: "A new project starts with no existing test assets. How do you approach testing from scratch?", coach: "Sequence matters: understand the product, then risk-based test design, then a thin automation skeleton on the stable core — resist building a framework before you understand what to test.", model: "First I learn the product and its risks — requirements, architecture, who the users are and what failure costs — because test assets built before that understanding get thrown away. Then I write test scenarios for the critical paths, risk-ordered, so there's manual coverage from day one. Automation starts as a thin skeleton: framework structure, CI hook, and smoke coverage of the few stable core flows, expanding only as the product stabilizes. In parallel I set up the basics people forget: defect workflow, test data strategy, environment access, and a traceability link from requirements to tests so coverage is measurable rather than claimed.", anchor: "Scenario bank Q3" },
    { track: "interview", type: "written", topic: "RISK", question: "You find a critical defect just before the production release. What do you do?", coach: "Show speed plus judgment: verify and document fast, quantify impact, bring options (fix/defer/workaround/partial rollback) to the go/no-go owners — QA informs the decision, not blocks unilaterally.", model: "First I verify it quickly and cleanly — exact reproduction steps, evidence, affected scope — because the next hour of decisions depends on the defect being real and understood. Then I get it in front of the release decision-makers immediately with impact quantified in business terms: who hits this, how often, what it costs. I come with options, not just the problem — fix and retest the affected area tonight, ship with a documented workaround, feature-flag it off, or slip the date — each with its risk. The release call belongs to the business, but my job is making sure it's made with full information, and whatever gets decided is written down with the sign-off attached.", anchor: "Scenario bank Q11" },
    { track: "interview", type: "written", topic: "PROCESS", question: "A production issue is reported by customers. How do you begin debugging?", coach: "Triage order: confirm scope and severity, reproduce from the customer's data, difference production against test coverage, then feed the escape back into the suite.", model: "First, scope: is it all users or a segment, is data being corrupted or just displayed wrong, and does it need an immediate mitigation like a rollback or feature flag before any root-causing. Then I reproduce it — customer's steps, data conditions, and environment, using production logs and monitoring to pin the failing component and the first bad timestamp, which often correlates with a specific deploy or config change. Once it's reproduced in a lower environment, the fix path is normal engineering. The QA-specific step is the last one: why didn't we catch it — missing scenario, environment gap, data condition we never modeled — and the escape becomes a regression test before the incident is closed.", anchor: "Scenario bank Q14" },
    { track: "interview", type: "written", topic: "VOICE", question: "Tell me about a situation where you prevented a production issue.", coach: "Pick one real story and tell it STAR-shaped: the signal you noticed that others missed, what you did about it, and the quantified consequence avoided. Specificity is the whole game.", model: "The shape that lands: 'During regression for a release, I noticed X — not a failing test, but a pattern that looked wrong' — the story is strongest when the catch came from judgment, not just a red assertion. Then the action: how you isolated it, proved it was real, and escalated with impact quantified. Then the outcome: what shipping it would have cost — wrong calculations, a compliance breach, a customer-facing outage — and what changed afterward, like a new automated check that class of defect can't get past again. Rehearse one specific story with real numbers; a generic 'I always test carefully' answer is a wasted question.", anchor: "Scenario bank Q15" },
    { track: "interview", type: "written", topic: "DESIGN", question: "Design test scenarios for a Login feature.", coach: "Organize out loud: positive, negative, security, session, and usability/edge — a structured tour beats a random list of twenty cases.", model: "Positive: valid credentials land on the right page, remember-me persists, case-handling of the username is per spec. Negative: wrong password, unknown user, blank fields, whitespace padding — and the error message must not reveal whether the username exists. Security: account lockout after N failures, password masked, no credentials in the URL or logs, SQL injection and XSS strings rejected, session cookie flagged HttpOnly/Secure, and the back button after logout doesn't restore the session. Session: expiry timeout, concurrent logins per policy, deep-link redirect back to the requested page after login. Edge: password at length limits, special characters, copy-paste into fields, and behavior under a slow or failed auth-service response.", anchor: "Scenario bank Q21" },
    { track: "interview", type: "written", topic: "DESIGN", question: "Design test scenarios for a Payment system.", coach: "Money means: correctness to the cent, idempotency on retry, every failure path, and security/compliance. Show you think in states — initiated, authorized, captured, failed, refunded.", model: "Functional: successful payment for each supported method, amount charged exactly matches order total including tax and currency rounding, and the order/payment/ledger records all agree. Failure paths: declined card, insufficient funds, expired card, gateway timeout — and critically, what state the order is left in for each: no money taken without an order, no order without money taken. Idempotency: user double-clicks pay or retries after a timeout — exactly one charge. Refunds and partial refunds reconcile back correctly. Security and compliance: card data never stored or logged in plain text (PCI), amounts can't be tampered with client-side. Then boundaries — zero, negative, maximum amounts, currency conversion — and concurrency, like two sessions paying for the same cart.", anchor: "Scenario bank Q22" },
    { track: "interview", type: "written", topic: "DESIGN", question: "Design test scenarios for a Search feature.", coach: "Cover relevance, matching behavior, input handling, result presentation, and performance — and say how you'd verify ranking, which is the part most answers skip.", model: "Matching: exact match, partial match, case-insensitivity, multi-word queries, and per-spec behavior for synonyms, plurals, and typos. Input handling: empty search, only spaces, special characters and SQL/HTML injection strings, very long queries, and non-Latin text. Results: zero-results shows a helpful empty state, result counts are accurate, pagination doesn't duplicate or drop items, and filters and sorts compose correctly with the query. Relevance is testable if you make it concrete: seed known data and assert that a title-exact match ranks above a description-only match per the ranking rules. Performance: response time on a production-sized index and behavior while the index is updating — does a just-added item appear within the documented delay.", anchor: "Scenario bank Q23" },
    { track: "interview", type: "written", topic: "DESIGN", question: "Design test scenarios for a Shopping Cart.", coach: "The cart is a state machine under concurrency: add/update/remove, persistence across sessions, price and inventory changes while items sit in the cart, and totals correctness.", model: "Core operations: add an item, update quantity, remove, add the same item twice — does it merge or duplicate per spec — and quantity boundaries: zero, max stock, above stock. Totals: line items, quantity math, tax, shipping, and discount codes all recompute correctly on every change, including stacked and expired coupons. Persistence: cart survives page refresh and logout/login per spec, and a guest cart merges correctly when the user signs in. The interesting cases are staleness: item price changes or the item goes out of stock while it's in the cart — what does checkout show, and does the final charge match what the user saw? Concurrency: same account in two tabs or devices editing the cart simultaneously.", anchor: "Scenario bank Q24" },
    { track: "interview", type: "written", topic: "DESIGN", question: "Design test scenarios for a File Upload feature.", coach: "Four axes: file type, file size, file content (including hostile), and the upload journey (progress, cancel, retry, concurrency). Security cases show seniority.", model: "Type validation: each allowed type succeeds, blocked types are rejected — including a renamed file, like an .exe with a .jpg extension, which tests content sniffing versus extension checking. Size: at the limit, one byte over, zero-byte file, and a very large file for timeout and progress behavior. Content and security: filename with special characters, path traversal names like ../../etc/passwd, a file carrying a script payload served back unescaped, duplicate filenames, and confirming the file is virus-scanned and stored outside the web root per spec. Journey: progress indicator accuracy, cancel mid-upload leaves no orphan, network drop and retry, multiple simultaneous uploads, and the uploaded file is retrievable and byte-identical afterward.", anchor: "Scenario bank Q25" },
    { track: "interview", type: "written", topic: "LEADERSHIP", question: "A team member is consistently missing deadlines. How do you handle it?", coach: "Private, diagnostic, then supportive with accountability. Name the possible root causes and show the escalation ladder only after coaching — jumping to performance-management first is a red flag.", model: "First a private one-on-one that starts diagnostic, not accusatory — 'I've noticed the last three deliverables slipped; walk me through what's happening.' The root cause changes everything: overloaded, blocked by dependencies they didn't escalate, a skill gap on new work, estimation trouble, or something personal. Most of those are fixable with rebalanced load, pairing, smaller task breakdowns, or teaching them to raise blockers early. Then clear expectations with a check-in cadence so progress is visible before the deadline, not after it's missed. If the pattern continues with support in place, it becomes a documented performance conversation — but escalating before coaching loses the person and teaches the team that struggling is unsafe to admit.", anchor: "Scenario bank Q43" },
    { track: "interview", type: "written", topic: "LEADERSHIP", question: "There is disagreement between QA and Development about release quality. What do you do?", coach: "Move the argument from opinions to evidence against pre-agreed criteria, quantify residual risk in business terms, and put the final call where it belongs — with the business owner, documented.", model: "I take the conversation off 'QA thinks versus dev thinks' and back to the exit criteria we agreed before the cycle — pass rates, open defects by severity, coverage of changed areas. If we never agreed criteria, that's the real lesson for next release. Then I present the risk in business terms: these three defects mean this behavior for this class of user at this frequency — because 'quality isn't good enough' is an opinion, but 'checkout fails for 5% of returning users' is a decision input. If disagreement remains, the go/no-go escalates to the product owner as a business decision with the evidence on the table, and whichever way it goes, it's documented with sign-off. QA's authority is the quality of its evidence, not veto power.", anchor: "Scenario bank Q44" },
    { track: "interview", type: "written", topic: "LEADERSHIP", question: "You are assigned as QA Lead for a new product. What is your 30-day plan?", coach: "Three phases roughly by decade: learn (product, people, process), assess (coverage, escapes, pipeline, pain points), then propose targeted changes with quick wins — resist restructuring anything in week one.", model: "Days 1–10 are listening: learn the product and its riskiest flows, meet the QA team one-on-one plus the dev leads and product owner, and understand the current process end to end — how work arrives, how bugs flow, what the release cadence is. Days 11–20 are assessment: map actual test coverage against risk, pull the last few months of production escapes to see what the process misses, review automation health — flakiness, run time, CI integration — and identify the top pain points the team already knows about. Days 21–30 are the plan: a short findings write-up, one or two quick wins delivered immediately for credibility — often a flaky-test cleanup or a triage process fix — and a prioritized 90-day roadmap agreed with my manager. The mistake to avoid is arriving with the improvement plan already written.", anchor: "Scenario bank Q47" },
    { track: "interview", type: "written", topic: "PROCESS", question: "How would you improve an existing QA process that has frequent production escapes?", coach: "Start with escape analysis — classify where each escape should have been caught — then fix the top leak categories rather than adding blanket process. Show measurement before and after.", model: "The escapes themselves are the diagnostic: I'd classify the last several months of production defects by where they should have been caught — missing test scenario, environment mismatch, untested data condition, regression gap, requirement misunderstanding — because each category has a different fix. Missing scenarios point to review practices and risk analysis; environment escapes point to test-environment fidelity; regression gaps point to suite coverage and change-based selection. Then I fix the top two or three leak categories with targeted changes and make 'escape becomes a regression test' a standing rule so each miss is a one-time miss. The measure of success is the escape rate trend over the following releases — process changes that don't move that number get reverted, not defended.", anchor: "Scenario bank Q48/Q50" },
    { track: "framework", type: "written", topic: "FRAMEWORK", question: "The application under test has a Windows-based desktop UI in front of a microservices backend. How would you approach automating the desktop UI?", coach: "Lead with your UFT/QTP depth — object identification, synchronization, checkpoints — then bridge: the discipline transfers to WinAppDriver/Appium or FlaUI, and most coverage should live at the API layer anyway with the desktop UI reserved for true end-to-end journeys.", model: "I've automated Windows-based UIs with UFT/QTP for years, and the transferable core is the same as Selenium: reliable object identification, explicit synchronization instead of sleeps, and keeping locators out of test logic. For a Java-centric stack I'd evaluate WinAppDriver or Appium's Windows driver — WebDriver protocol, so it slots into the existing framework, waits, and reporting — or FlaUI over UI Automation if deeper control identification is needed. Strategically, I'd push most validation to the API layer where it's fast and stable, and reserve desktop-UI automation for the critical end-to-end journeys that prove the UI and services agree — the same test-pyramid reasoning as web, just with a different driver at the top.", anchor: "Luxoft VR-123702 gap — Windows desktop UI automation" },
    { track: "framework", type: "written", topic: "PERFORMANCE", question: "Walk me through building a JMeter test plan from scratch for a calculation API.", coach: "Name the actual components in order — thread group, config elements, samplers, assertions, listeners — plus CSV-driven unique data, GUI-for-build/CLI-for-run, and what you look at in the results.", model: "I start with a Thread Group defining users, ramp-up, and duration, sized from the real traffic profile rather than a round number. Under it: an HTTP Request Defaults config so host and headers live in one place, a CSV Data Set Config feeding each thread unique calculation inputs — critical, because identical inputs hit caches and measure nothing — and the HTTP samplers for the endpoints under test. Each sampler gets a Response Assertion on status and a JSON Assertion on a key calculated field, because a fast wrong answer is still a failure. I build and debug in the GUI with a View Results Tree, but the real run is CLI — jmeter -n -t plan.jmx -l results.jtl — since GUI mode distorts load. Afterward I read the Aggregate Report focusing on p90/p95 and error rate, not averages, and correlate spikes with server-side metrics to tell an app bottleneck from an environment artifact.", anchor: "Luxoft VR-123702 gap — JMeter hands-on workflow" },
    { track: "api", type: "mcq", topic: "CUCUMBER", question: "How do Cucumber and Spring Boot actually integrate in a test framework?", options: ["Cucumber replaces the Spring context entirely", "A class annotated @CucumberContextConfiguration (typically with @SpringBootTest) boots the Spring context once; step-definition classes become Spring-managed beans, so shared state and services are injected via @Autowired instead of statics", "Each step definition must call SpringApplication.run() itself", "They cannot be combined; choose one framework"], answer: 1, explanation: "The cucumber-spring module wires Cucumber's glue into Spring's DI. One glue class carries @CucumberContextConfiguration + @SpringBootTest to start the context, and every step class is a bean — so a scenario-scoped shared-state bean or a REST client service is constructor/field injected, solving cross-step state cleanly. Know that the context boots once and scenario-scoped beans reset per scenario.", anchor: "Luxoft VR-123702 gap — cucumber-spring glue", employers: ["luxoft"] },
    { track: "interview", type: "written", topic: "UAT / RELEASE", question: "How do you prepare a workstream for UAT and production validation?", coach: "Cover business-critical scenarios, entry and exit criteria, access and test data, defect triage, production smoke checks, and rollback or hypercare readiness.", model: "I prepare UAT by translating the system-test coverage into a short set of business-critical journeys, then confirm entry criteria: the environment is stable, the right users have access, the data is representative and approved, and no unresolved blocker makes the results meaningless. During UAT I keep triage and evidence disciplined so business feedback becomes actionable defects rather than a parallel informal queue. For production I agree the smoke scenarios, monitoring and support contacts, validation data, and rollback or hypercare plan before deployment. The Test Lead's job is to make the handoff observable and reversible, not to declare success because the deployment completed.", anchor: "Maximus JD gap — UAT and Production phases" },
    { track: "interview", type: "mcq", topic: "AGILE / SAFE", question: "In a large Agile or SAFe implementation, a workstream is behind planned test execution. What should the Test Lead do first?", options: ["Wait until the exit gate so the schedule variance is final", "Report only the percentage complete and let Program Test Management diagnose it", "Quantify planned versus actual work, identify the cause and dependencies, propose recovery options, and escalate the business impact early", "Add more testers immediately without checking requirements, data, or environment constraints"], answer: 2, explanation: "A useful lead response turns variance into a decision: what was planned, what actually happened, why the gap exists, what can recover it, and what risk remains if it cannot. The same view should roll up cleanly to Program Test Management and the broader release cadence.", anchor: "Maximus JD gap — Agile/SAFe execution oversight" },
    { track: "interview", type: "written", topic: "DEFECT / JIRA", question: "How do you use JIRA to report and track a defect through resolution in a complex automation project?", coach: "Cover a reproducible report, evidence, severity versus priority, ownership, workflow states, links to requirements/tests, retest results, and trend visibility for the team.", model: "I create one defect with a precise title, environment and build, preconditions, repeatable steps, expected versus actual behavior, severity, business impact, and evidence such as logs, request/response data, screenshots, or a failing automation link. I link it to the requirement, test case, or story so coverage and traceability do not disappear into a ticket queue, then assign the right owner and keep the workflow state current as it moves through triage, development, ready-for-test, retest, and closure. On retest I record the build and result rather than just closing the ticket. For the lead view I use JIRA filters or dashboards for open defects by severity, age, assignee, reopen rate, and trend so defect management supports release decisions instead of becoming clerical status work.", anchor: "Luxoft JD gap — JIRA defect and test management", employers: ["builders-mutual"] },
    { track: "interview", type: "written", topic: "API INTEGRATION", question: "How would you design an API integration test strategy for a digital experience that moves data across multiple applications and services?", coach: "Start with the system and data-flow map, then cover contracts, authentication, business rules, negative paths, retries, idempotency, test data, observability, and the boundary between API, integration, and end-to-end coverage.", model: "I start by mapping the business workflow and the data lineage across each producer, consumer, middleware step, and persistence boundary. For each API I document the contract from Swagger or OpenAPI, authentication and authorization, required and optional fields, business rules, error responses, and correlation identifiers. The integration suite then proves mapping and state transitions across systems: valid flows, missing or malformed data, duplicates, timeouts, retries, partial failure, replay, and eventual consistency. I keep fast contract and service checks separate from a smaller set of end-to-end customer journeys, use controlled data or stubs for unavailable dependencies, and capture request, response, correlation ID, and downstream evidence so failures identify the boundary that broke rather than just saying the workflow failed.", anchor: "Builders Mutual JD gap — API integration and data movement" },
    { track: "interview", type: "written", topic: "SOLE QA", question: "You are the only QA on a new Digital Experience team. What would you do in your first 30 days?", coach: "Show self-direction: stakeholder and system discovery, risk baseline, test strategy, defect workflow, automation priorities, environment/data needs, and a communication cadence.", model: "I would not begin by writing a large automation suite in isolation. First I would map the customer journeys, integrations, environments, release cadence, and the people who own product, development, data, and operations. Then I would baseline risk and coverage: what is already tested, where data moves between systems, which failures matter most to customers, and what is missing from the current defect and release process. I would publish a short test strategy with entry and exit criteria, API-first automation priorities, a small set of critical UI journeys, test-data and AWS dependencies, and a visible defect workflow. I would establish a weekly quality readout early so being the only QA never becomes being the only person who knows the risk.", anchor: "Builders Mutual JD gap — sole QA operating model" },
    { track: "interview", type: "mcq", topic: "SDLC", question: "For an API-integration-heavy digital experience, which statement best describes how testing should fit across the SDLC?", options: ["Testing is a phase that starts only after all development finishes", "Testing spans the SDLC — contract and requirement review during design, test planning and stubbing during development, full integration and regression before release, and monitoring or smoke checks after release — so defects are caught closest to where they were introduced", "SDLC only describes waterfall projects, so it doesn't apply to an Agile team", "QA's only SDLC responsibility is executing the regression suite before sign-off"], answer: 1, explanation: "Shift-left means testing activities attach to every SDLC phase, not just a test phase at the end: reviewing the API contract and acceptance criteria during design, building test plans and stubs alongside development, running integration/regression before release, and validating in production after. Agile compresses this into every sprint rather than removing it — the phases still exist, just on a shorter cycle.", anchor: "Builders Mutual JD gap — SDLC fundamentals" },
    { track: "interview", type: "mcq", topic: "TOOL STRATEGY", question: "A digital experience has API integrations plus a small number of critical browser journeys. How should Playwright, Selenium, and API tests be used together?", options: ["Put every scenario in browser automation so it reflects the user", "Use API tests for contracts, data movement, and business rules; use Playwright or Selenium for critical user journeys, accessibility-relevant behavior, and browser-specific risks; avoid duplicating the same coverage at every layer", "Use Selenium only because API tests cannot validate integrations", "Use Playwright to replace all service and database validation"], answer: 1, explanation: "The test pyramid still applies. API and integration checks provide the strongest signal for service contracts, data movement, and business rules. Browser automation proves the highest-value customer journeys and browser behavior. Playwright and Selenium are alternatives to evaluate for the UI layer, not reasons to duplicate every test twice.", anchor: "Builders Mutual JD gap — Playwright/Selenium/API strategy" },
    { track: "interview", type: "written", topic: "MIDDLEWARE", question: "How would you test a Workato recipe or another enterprise middleware integration?", coach: "Cover trigger conditions, field mapping, authentication, happy and failure paths, retries, duplicate delivery, idempotency, observability, and reconciliation at both ends.", model: "I would treat the recipe as a system boundary with an input contract, transformation rules, an output contract, and operational behavior. I would test valid and invalid triggers, required and optional fields, type and mapping transformations, authentication failures, downstream 4xx and 5xx responses, timeouts, retries, duplicate delivery, ordering, and partial failure. I would verify the source and target records, not just a successful job status, and use correlation IDs or run history to trace one business event through the workflow. The important questions are whether a replay creates duplicate business effects, whether a failed step is recoverable, and whether the team can detect and reconcile a message that was accepted by one system but not the next.", anchor: "Builders Mutual JD gap — Workato and middleware testing" },
    { track: "interview", type: "written", topic: "WHITE / GRAY BOX", question: "What is the difference between white-box and gray-box testing, and where would each help in a complex integrated system?", coach: "Define the tester's level of internal knowledge, then connect each approach to risk, data validation, interfaces, logs, and business-facing end-to-end coverage.", model: "White-box testing uses detailed knowledge of the implementation — code paths, branches, queries, or service internals — to target coverage that black-box behavior alone may miss. Gray-box testing uses partial internal knowledge, such as API contracts, database relationships, message schemas, logs, or deployment topology, while still validating behavior from a user's or system consumer's perspective. In an integrated web system I would use white-box collaboration for targeted unit or service-level gaps and gray-box investigation to reconcile API results to database state, trace an interface failure, or choose high-value end-to-end scenarios. The goal is not to expose implementation for its own sake; it is to shorten diagnosis and improve coverage of the real risk.", anchor: "Maximus JD gap — white/gray-box testing", employers: ["builders-mutual"] },
    { track: "interview", type: "mcq", topic: "PLAYWRIGHT", question: "What is the most accurate description of Playwright's auto-waiting compared to Selenium's waits?", options: ["Playwright removes the need to think about timing at all", "Playwright performs actionability checks before every action — visible, stable, enabled, receives events — so most explicit waits disappear, but you still assert on state and set timeouts for app-specific conditions", "Playwright uses a global implicit wait like Selenium", "Selenium auto-waits and Playwright does not"], answer: 1, explanation: "Playwright retries actionability checks (attached, visible, stable, enabled, not obscured) up to the timeout before clicking or typing, and web-first assertions like expect(locator).toBeVisible() retry too. That kills most boilerplate waits, but conditions the framework cannot see — a spinner finishing, a queue draining — still need an explicit expectation.", anchor: "Builders Mutual JD gap — Playwright auto-waiting" },
    { track: "interview", type: "mcq", topic: "PLAYWRIGHT", question: "Which Playwright locator approach best survives a UI refactor, and what does strict mode do?", options: ["XPath by absolute position; strict mode disables retries", "Role- and text-based locators (getByRole, getByLabel, getByTestId); strict mode fails the test when a locator resolves to more than one element", "CSS by generated class name; strict mode picks the first match silently", "Chained indexes; strict mode ignores duplicates"], answer: 1, explanation: "User-facing locators (getByRole/getByLabel/getByText) plus stable test IDs track intent rather than markup, so styling changes do not break them. Strict mode is the safety net: if a locator matches multiple nodes it errors instead of quietly acting on the first one — the ambiguity that Selenium's findElement hides.", anchor: "Builders Mutual JD gap — Playwright locators" },
    { track: "interview", type: "mcq", topic: "PLAYWRIGHT", question: "A Playwright test fails only in CI. Which built-in artifact gives the fastest root cause?", options: ["Re-run it locally until it fails", "The trace file opened in the Playwright trace viewer — DOM snapshots per action, network log, console output, and screenshots on a timeline", "The stack trace alone", "Increase the timeout and move on"], answer: 1, explanation: "Configure trace on-first-retry plus video and screenshot on failure. The trace viewer replays each action with a before/after DOM snapshot, the network calls, and console output, so you can separate a genuine app defect from a timing or data problem without reproducing locally.", anchor: "Builders Mutual JD gap — Playwright trace viewer" },
    { track: "interview", type: "mcq", topic: "PLAYWRIGHT", question: "How can Playwright support API-focused testing, not just browser testing?", options: ["It cannot; you must use a separate HTTP client", "Its APIRequestContext issues HTTP calls directly, can share cookies and auth state with a browser context, and is commonly used to seed or verify data around a UI journey", "It proxies all API calls through the browser UI", "Only via a third-party plugin"], answer: 1, explanation: "Playwright's request fixture is a first-class HTTP client with the same assertion library. Practical uses: set up test data through the API before a UI test, log in once and reuse storageState instead of driving the login form every time, and verify a downstream record after a UI action.", anchor: "Builders Mutual JD gap — Playwright API testing" },
    { track: "interview", type: "written", topic: "PLAYWRIGHT", question: "Your Selenium background is deep and this role names Playwright. How do you answer 'how quickly could you be productive in Playwright?'", coach: "Be honest about depth, then show the transfer: the hard parts of automation are design, waits, data, and CI — not the API surface. Name specific Playwright concepts to prove you have actually looked at it.", model: "My production depth is in Selenium and Java, and I would rather say that plainly than overclaim. What transfers is everything that actually makes a suite trustworthy: locator strategy, deterministic waiting, page or component objects, test data ownership, parallel isolation, CI integration, and triage discipline. Playwright changes the syntax and gives me things I had to build by hand — actionability-based auto-waiting, web-first retrying assertions, strict-mode locators, worker-level parallelism with isolated browser contexts, storageState for auth reuse, and the trace viewer for CI failures. I would expect to be writing useful tests in the first week and contributing to framework structure inside two or three sprints. The risk is not learning the API; it is carrying over Selenium habits like sprinkling sleeps or over-driving the UI for setup the API should do, and I know to watch for that.", anchor: "Builders Mutual JD gap — Playwright ramp-up honesty" },
    { track: "interview", type: "mcq", topic: "AWS", question: "You must validate an event-driven flow: a service publishes to SNS, an SQS queue feeds a Lambda, and the Lambda writes to a data store. What proves the flow end to end?", options: ["Assert the publish call returned 200 and stop", "Trigger with a known correlation ID, then assert the downstream persisted record, check the Lambda's CloudWatch logs for that ID, and confirm the dead-letter queue stayed empty", "Wait 30 seconds and check the UI", "Only test the Lambda in isolation with a unit test"], answer: 1, explanation: "A 200 from the publisher proves acceptance, not delivery. The real assertions are the persisted downstream state, the log trail for that correlation ID across hops, and an empty DLQ. Then test the failure side: poison message, retry behavior, and duplicate delivery, since SQS standard queues are at-least-once.", anchor: "Builders Mutual JD gap — AWS event-driven validation" },
    { track: "interview", type: "mcq", topic: "AWS", question: "An integration intermittently fails in an AWS environment. Which investigation gives the strongest root-cause evidence?", options: ["Re-run the test suite until it passes", "Query CloudWatch Logs Insights by correlation or request ID across the API Gateway, Lambda, and downstream log groups, and line it up with metrics such as throttles, errors, and duration", "Ask the developer to check locally", "Increase all test timeouts"], answer: 1, explanation: "Distributed failures are traced, not guessed. Filter each log group by the same correlation ID to find the hop that broke, then confirm the pattern against metrics — Lambda throttles or timeouts, 5xx counts, queue age. X-Ray does the same job visually. That is what turns 'flaky' into a defect a developer can act on.", anchor: "Builders Mutual JD gap — AWS troubleshooting" },
    { track: "interview", type: "mcq", topic: "AWS", question: "A test must verify file-based ingestion: a partner drops a CSV into S3 and records should appear in the application. What is the sound approach?", options: ["Manually upload through the console each time", "Automate the upload with the AWS SDK using a scoped test-only IAM role and a unique key, then poll for the processed record with a bounded timeout and assert both the row content and the malformed-file failure path", "Assert only that the object exists in the bucket", "Skip it — file ingestion cannot be automated"], answer: 1, explanation: "Own the whole loop: put the object programmatically, use a unique key so parallel runs do not collide, poll for downstream state instead of sleeping, and clean up. Then test the ugly cases — bad header, wrong encoding, partial file, duplicate delivery — and verify rejected files land where operations can see them.", anchor: "Builders Mutual JD gap — AWS S3 ingestion testing" },
    { track: "interview", type: "mcq", topic: "AWS", question: "Calling an API through AWS API Gateway, you see a 403, then later a 502. What do these usually tell you?", options: ["Both mean the API is down", "403 is typically authorization, signature, WAF, or a missing API key at the gateway; 502 means the gateway reached the integration but got a bad or malformed response from it", "403 means the record was not found; 502 means throttling", "They are interchangeable gateway noise"], answer: 1, explanation: "Knowing where the status originates saves hours. 401 and 403 usually never reach the backend — authorizer, key, IAM signature, or WAF. 502 means the integration responded badly, 504 is an integration timeout, and 429 is throttling. Capture the request ID from the response headers and hand that to the developer.", anchor: "Builders Mutual JD gap — API Gateway status triage" },
    { track: "interview", type: "written", topic: "AWS", question: "What changes about your QA approach when the application under test runs in AWS rather than on-prem?", coach: "Cover environment parity, credentials and IAM, observability, eventual consistency, cost and data hygiene, and the services you actually touch as a tester.", model: "The functional testing does not change; the operating context does. Access becomes IAM-shaped, so I use a scoped test role and pull credentials from Secrets Manager or Parameter Store instead of a checked-in properties file. Observability improves and I lean on it: CloudWatch logs and metrics, correlation IDs, and X-Ray become primary evidence in defect reports rather than screenshots. The architecture is more asynchronous, so I stop asserting immediately after a call and poll for downstream state with a bounded timeout, and I add coverage for retries, duplicate delivery, and dead-letter handling. Environment parity matters more — a lower environment with stubbed integrations will not catch IAM, VPC, or throttling problems, so I state which risks are only provable in a production-like environment. I also treat test data and infrastructure as things I clean up, because leftover queues, objects, and records cost money and corrupt later runs.", anchor: "Builders Mutual JD gap — testing cloud applications in AWS" },
    { track: "interview", type: "mcq", topic: "DATA MOVEMENT", question: "You must prove data moved correctly from a source system through middleware into a target system. What is the strongest validation?", options: ["Confirm the integration job reported success", "Reconcile source and target on record counts, key-level field-by-field comparison across a sampled and boundary-heavy set, transformed values, and rejected-record handling", "Spot-check one record in the UI", "Compare only the total row counts"], answer: 1, explanation: "Counts alone hide truncation, mapping errors, timezone and precision shifts, and silently dropped rows. Reconcile counts first as a cheap tripwire, then compare keys and transformed fields — especially nulls, defaults, max lengths, decimals, dates, and special characters — and prove rejected records are visible somewhere rather than lost.", anchor: "Builders Mutual JD gap — data movement reconciliation" },
    { track: "interview", type: "mcq", topic: "DATA MOVEMENT", question: "An integration is eventually consistent — the target record appears anywhere from 1 to 20 seconds later. How should the automated check be written?", options: ["Sleep for 20 seconds before asserting", "Poll the target on a short interval with a bounded overall timeout, fail with the last observed state, and treat the observed latency itself as a reportable measurement", "Assert immediately and mark the test flaky", "Retry the whole test three times"], answer: 1, explanation: "A fixed sleep pays the worst case every run and still breaks when the system is slower. Bounded polling — an Awaitility-style loop or a retrying assertion — passes as soon as the state is right and fails with useful diagnostics. Recording how long it took turns a vague 'sometimes slow' into data. Blanket test-level retries just hide real defects.", anchor: "Builders Mutual JD gap — eventual consistency assertions" },
    { track: "interview", type: "mcq", topic: "DATA MOVEMENT", question: "Why does idempotency matter when testing integrations, and how do you test it?", options: ["It does not matter if the happy path works", "Networks retry: send the same request or event twice with the same idempotency key or message ID and assert one business effect — one record, one payment, one notification — plus a sane response to the duplicate", "Idempotency is only a developer concern", "Test it by sending two different payloads"], answer: 1, explanation: "At-least-once delivery, client retries, and manual replays all mean a message can arrive twice. The test is: replay the identical request and prove the downstream state changed once. Related cases are out-of-order delivery, a retry after a timeout where the first call actually succeeded, and whether replaying a failed batch is safe for operations.", anchor: "Builders Mutual JD gap — idempotency and duplicate delivery" },
    { track: "interview", type: "mcq", topic: "CONTRACT", question: "The team publishes a Swagger/OpenAPI spec. How do you use it beyond reading endpoint names?", options: ["Only to find the base URL", "Generate the test baseline from it — required fields, types, enums, formats, status codes — validate live responses against the schema, and diff spec versions to catch breaking changes before consumers do", "Trust it as proof the API behaves correctly", "Import it once and never look again"], answer: 1, explanation: "The spec is the contract and also a test oracle. Schema-validate real responses so drift shows up as a failure, drive negative cases from the declared constraints, and diff the spec between builds — a removed field, a narrowed enum, or a changed required flag is a breaking change for every downstream consumer. A spec that disagrees with the implementation is itself a defect.", anchor: "Builders Mutual JD gap — Swagger/OpenAPI contract testing" },
    { track: "interview", type: "mcq", topic: "TOOLING", question: "You have a large Postman collection for exploratory API work. How should it relate to the automated suite?", options: ["Postman is enough; skip coded tests", "Keep Postman for exploration, documentation, and stakeholder demos, run collections in CI with Newman where they earn it, and move durable regression coverage into code for version control, reuse, and data setup", "Delete Postman once automation exists", "Maintain both as full duplicates of each other"], answer: 1, explanation: "Postman is excellent for discovery, sharing a reproducible request with a developer, and quick environment-driven checks, and Newman makes it CI-runnable. But collections are awkward to refactor, review, and share logic across. The durable regression layer belongs in code next to the application, with the collection kept as an exploration and documentation asset rather than a second unmaintained suite.", anchor: "Builders Mutual JD gap — Postman/Newman vs coded suites" },
    { track: "interview", type: "written", topic: "ROOT CAUSE", question: "An API returns 200 OK but the record never appears in the downstream system. Walk through your root-cause analysis.", coach: "Show a boundary-narrowing method, not a guess list: reproduce with a correlation ID, verify each hop, separate accepted from processed, then write a defect that names the failing boundary with evidence.", model: "First I reproduce with a controlled payload and a correlation ID I can trace. Then I narrow the boundary rather than speculate. I confirm what the 200 actually means, because many asynchronous APIs return accepted, not processed, and I check the response body for a job or message ID. I follow that ID through the hops: did the message reach the queue or middleware, did the consumer pick it up, did it error, did it land in a dead-letter queue, and what do the logs say at each step. I query the target directly rather than trusting the UI, because a caching or read-model lag looks identical to a lost record. I also diff a working payload against the failing one, since mapping, field length, encoding, or a field that is optional upstream but required downstream is a common cause. Then I write the defect with the request, response, correlation ID, timestamps, the log line from the hop that broke, and whether the data is recoverable — so the developer starts at the failure and operations know whether existing records need reconciliation.", anchor: "Builders Mutual JD gap — integration root-cause analysis" },
    { track: "interview", type: "written", topic: "TEST PLAN", question: "How do you design and document an API test plan and test cases so developers and business stakeholders can both use them?", coach: "Cover scope, the data-flow map, per-endpoint case design, non-functional angles, environments and data, entry and exit criteria, traceability, and how the automation maps back to it.", model: "I start with scope and a data-flow map: which services and systems participate, what business process the data supports, and where the risky boundaries are. For each endpoint I document the contract from the spec, authentication and authorization, then design cases in layers — happy path, required and optional field validation, boundaries, data types and formats, business rules, error responses with their codes and messages, authorization negatives, and the integration effect on the downstream system. Around that I capture the non-functional checks that matter: response time expectations, payload size, pagination, rate limiting, and sensitive data exposure. The plan states environments, test data ownership and refresh, dependencies and stubs, entry and exit criteria, and risks. Each case traces to a requirement or story, and the automated tests carry the same identifiers so coverage is answerable rather than assumed. I keep the artifact short and living — a readable document plus the suite itself as the executable spec — because a plan nobody reads is not a control.", anchor: "Builders Mutual JD gap — API test plan documentation" },
    { track: "interview", type: "mcq", topic: "MIDDLEWARE", question: "You are testing an integration whose downstream partner system is unavailable in the test environment. What is the professional approach?", options: ["Skip the tests until the partner is available", "Stub the partner at the boundary with WireMock or a service virtualization layer to prove your side's contract handling, retries, and error paths — while explicitly flagging which risks remain provable only against the real system", "Point the tests at the partner's production system", "Assume the integration works if the code compiles"], answer: 1, explanation: "Stubbing lets you test deterministically and cover failure modes a real partner rarely reproduces on demand — 500s, timeouts, malformed payloads, slow responses. The professional part is being explicit that stubs prove your handling, not the real contract, so you still schedule a connectivity or end-to-end verification window and say so in the test plan rather than letting green tests imply more than they cover.", anchor: "Builders Mutual JD gap — stubbing unavailable partners" },
    { track: "interview", type: "mcq", topic: "TEST MANAGEMENT", question: "The JD lists Quality Center/ALM, TestComplete, and Zephyr alongside Selenium. What's the actual difference in role between a test management tool and your automation framework?", options: ["They are competitors; you only need one", "A test management tool (Quality Center/ALM, Zephyr) owns test case authoring, the test portfolio, requirement-to-test traceability, execution tracking, and reporting; Selenium/Playwright executes the automated tests and reports pass/fail back into it via API or CI integration", "TestComplete replaces the need for a test management tool entirely", "Test management tools are only for manual testers and have no automation integration"], answer: 1, explanation: "Quality Center/ALM, Zephyr, and similar tools manage the portfolio — cases, traceability, execution history, coverage reporting. Selenium/Playwright/TestComplete execute tests. In a mature shop, automated runs report results back into the management tool via API/plugin so portfolio-level reporting stays accurate without manual re-entry.", anchor: "Builders Mutual JD gap — test management tooling (Quality Center/Zephyr)", employers: ["builders-mutual"] },
    { track: "interview", type: "mcq", topic: "TEST TYPES", question: "How do non-functional testing, edge-case testing, and exploratory testing actually differ, and when does each belong in a cycle?", options: ["They're interchangeable names for the same activity", "Non-functional testing validates qualities like performance, load, security, and usability rather than a specific business rule; edge-case testing targets boundary and unusual-input conditions within a functional test; exploratory testing is time-boxed, unscripted investigation guided by tester judgment, usually run alongside or after scripted coverage to find what the test cases didn't anticipate", "Exploratory testing means testing without any plan or purpose, so it should be avoided in a professional process", "Edge-case testing is a synonym for exploratory testing"], answer: 1, explanation: "Non-functional is about system qualities (load, performance, security, accessibility); edge-case is boundary/unusual-input coverage within functional test design; exploratory is a disciplined, time-boxed, charter-driven investigation — not aimless clicking — that surfaces gaps scripted cases miss. All three earn a deliberate slot in the plan, not just leftover time.", anchor: "Builders Mutual JD gap — non-functional, edge-case, and exploratory testing", employers: ["builders-mutual"] },
    { track: "interview", type: "written", topic: "PEER REVIEW", question: "The JD asks you to lead peer and vendor reviews of testing. Walk through how you run one.", coach: "Name what's being reviewed (test plan/cases/results), the review structure, how vendor-authored work gets extra scrutiny, and what a good review actually produces.", model: "I circulate the artifact — test plan, case set, or a vendor's test results — ahead of time so the session is discussion, not first-read. I run the review against a short checklist: does coverage map to requirements and risk, are cases specific enough to execute without the author in the room, are edge and negative cases present, and for a vendor deliverable, is the evidence (logs, screenshots, environment, data) sufficient to trust a passed result rather than take it on faith. I keep the room focused on gaps and risk, not style nitpicks, and I make sure every finding gets an owner and a close-out check, not just a comment. For vendor work specifically, I treat 'passed' as a claim to verify, not a fact — spot-checking a sample of their executed cases myself before I sign off protects the whole team's credibility on that deliverable.", anchor: "Builders Mutual JD gap — leading peer and vendor test reviews", employers: ["builders-mutual"] },
    { track: "interview", type: "mcq", topic: "UNIT TEST REVIEW", question: "You're asked to review a developer's unit test plan before a change merges. What are you actually checking for?", options: ["Only that tests exist and the build is green", "That the tests cover the actual business logic and branches (not just the happy path), boundary and error conditions are asserted, mocks aren't hiding an untested integration point, assertions check real outcomes rather than just 'no exception thrown', and the coverage lines up with what your own system/integration tests will assume is already proven at the unit level", "Line coverage percentage alone", "Whether the developer used the same testing framework as QA"], answer: 1, explanation: "A green suite with weak assertions or happy-path-only coverage gives false confidence. The review value QA adds is checking that unit tests actually pin down behavior and edge cases — because your system/integration test plan is built assuming certain logic is already proven at the unit level, and a gap there becomes a gap in overall coverage, not just a developer problem.", anchor: "Builders Mutual JD gap — reviewing developer unit test plans", employers: ["builders-mutual"] },
    { track: "interview", type: "mcq", topic: "DIAGRAMMING", question: "The JD names Functional Decomposition, Data Flow Diagrams, and Activity Diagrams. What is each actually best used for when you're designing test coverage?", options: ["They're interchangeable ways to draw the same box-and-arrow diagram", "Functional Decomposition breaks a system into its component functions/features to scope what needs coverage; a Data Flow Diagram traces how data moves and transforms between processes and stores, which is exactly what you need to plan integration/data-validation tests; an Activity Diagram models the sequence of actions and decision branches in a workflow, useful for mapping test scenarios and their branch conditions", "Data Flow Diagrams are only for database administrators, not testers", "Activity Diagrams replace the need for test cases entirely"], answer: 1, explanation: "These are requirements-analysis tools that double as test-design aids: Functional Decomposition gives you a coverage checklist by breaking scope into functions; a Data Flow Diagram is the fastest way to see every hop data crosses (and therefore every boundary an integration test should check); an Activity Diagram's decision branches map almost directly onto test scenario/condition tables.", anchor: "Builders Mutual JD gap — Functional Decomposition, Data Flow, and Activity Diagrams", employers: ["builders-mutual"] },
    { track: "interview", type: "written", topic: "SCRIPTING", question: "The JD expects excellent command of a scripting language like JavaScript. Your background is mostly Java. Where does JavaScript actually come up in test work, and how would you answer this in an interview?", coach: "Be honest about depth, but show you know the concrete places JS shows up even in a Java-centric framework — don't just say 'I can learn it.'", model: "I'd be direct that my production depth is Java, then name where JavaScript already touches automation work: Selenium's JavascriptExecutor for scrolling, forcing a click through an overlay, or reading a value the DOM API won't expose cleanly; browser console scripts when debugging a page live; and that most modern browser-native tooling — Playwright's own test runner, Cypress, and page.evaluate() calls — is JavaScript/TypeScript first. I'd also point out that reading and lightly modifying front-end JS is often enough for QA purposes — you don't need to build the app in it, you need to understand event handlers, async timing, and what a network call in the browser actually looks like, which is exactly the same judgment I already apply in Java. I'd commit to closing the gap quickly given that overlap rather than overstating current fluency.", anchor: "Builders Mutual JD gap — JavaScript scripting fluency", employers: ["builders-mutual"] },
    { track: "interview", type: "mcq", topic: "IMPACT ANALYSIS", question: "You're asked to perform impact analysis on a proposed modification to an existing application before regression testing begins. What does that actually involve?", options: ["Trust the developer's stated scope and only retest the changed screen", "Map the change against a dependency/data-flow view of the system to find every consumer, integration, and shared component it touches, classify the blast radius (isolated vs. shared/high-fan-out code), and size the regression scope — smoke, targeted, or full — to match the actual risk instead of the assumed one", "Run the full regression suite for every change regardless of size", "Skip impact analysis for changes labeled as bug fixes"], answer: 1, explanation: "Impact analysis is a targeting exercise: a change to shared/high-fan-out code (a common service, a shared component, a core data model) has a wide blast radius even if the code diff is small, while an isolated UI tweak may not. Getting the regression scope right — not defaulting to 'test everything' or 'trust the diff' — is the actual skill the JD is naming.", anchor: "Builders Mutual JD gap — impact analysis for regression scope", employers: ["builders-mutual"] },
    { track: "interview", type: "mcq", topic: "AI-ASSISTED QA", question: "The JD asks for familiarity with AI-assisted QA tools. What is the most credible description of where AI actually helps a test automation program today?", options: ["AI can replace the automation framework — you describe the app in plain English and it maintains the suite for you", "AI accelerates specific, reviewable tasks — drafting test cases and edge cases from acceptance criteria, generating first-pass page objects or API tests from a spec, self-healing locators, triaging flaky-failure clusters, and summarizing coverage gaps — while a human still owns the oracle, the risk model, and whether a failure is real", "AI has no legitimate place in QA because its output cannot be trusted", "AI is only useful for writing the test data"], answer: 1, explanation: "The honest answer names concrete leverage points and keeps the human accountable for correctness. Self-healing locators and AI-drafted cases save time but can also mask a genuine regression, so anything AI produces enters the suite through the same review gate as hand-written code. Claiming AI replaces the framework signals you have not run it in a real pipeline.", anchor: "Inn-Flow JD gap — AI-forward quality engineering" },
    { track: "interview", type: "written", topic: "AI-ASSISTED QA", question: "How would you introduce an AI-assisted testing tool into an existing suite without lowering the trust bar on the pipeline?", coach: "Show a pilot-then-measure approach with explicit guardrails: scope, review gate, metrics, and a rollback condition. Avoid both hype and blanket refusal.", model: "I would pilot it on a bounded slice rather than the whole suite — say, generating first-draft API tests from the OpenAPI spec, or self-healing locators on one non-critical journey. Everything the tool produces goes through code review like any other pull request, so a generated assertion never lands unread. I would baseline the metrics I care about before the pilot: authoring time per test, flake rate, escaped defects, and pipeline duration. If self-healing is involved, I insist the heal is reported as a warning on the run, not silently applied, because a locator that changed may be the bug. After a few sprints I compare against the baseline and either expand, adjust scope, or stop. The point is that AI changes how fast tests get written, not who is accountable for whether they are correct.", anchor: "Inn-Flow JD gap — adopting AI QA tooling safely" },
    { track: "interview", type: "mcq", topic: "CYPRESS VS SELENIUM", question: "The JD names Cypress, Playwright, and Selenium. What is the most accurate architectural difference between Cypress and Selenium?", options: ["Cypress is simply a newer Selenium wrapper with nicer syntax", "Cypress runs inside the browser's event loop in the same run-loop as the app, which gives automatic waiting, time-travel debugging, and native network stubbing, but constrains it to browser-context JavaScript and makes multi-tab/multi-origin and non-Chromium coverage harder; Selenium drives the browser externally over WebDriver, so it is language-agnostic and broader in browser and OS reach but needs explicit wait strategy", "Cypress cannot stub network calls", "Selenium runs in-browser and Cypress drives it externally"], answer: 1, explanation: "The in-browser vs. out-of-process distinction explains almost every practical trade-off: Cypress's auto-retry and network interception fall out of running in the same event loop, and so do its historical limits around multiple tabs, cross-origin flows, and non-JS languages. Selenium's external WebDriver protocol is why it spans languages, browsers, and grids at the cost of owning your own wait strategy.", anchor: "Inn-Flow JD gap — Cypress vs Selenium architecture" },
    { track: "interview", type: "written", topic: "REACT UI TESTING", question: "What changes about your UI automation approach when the front end is a React single-page application?", coach: "Cover SPA-specific waiting, locator strategy against generated markup, network-driven state, and where component tests belong versus end-to-end.", model: "The biggest change is that there is no page load to anchor on — the DOM re-renders in response to state and network calls, so waiting on document readiness is meaningless. I wait on the specific condition that matters: the element being visible and stable, or the XHR/fetch the render depends on completing. Locators matter more too, because class names are often generated or utility-based, so I push for stable test IDs (data-testid) or accessible roles and names rather than brittle CSS chains. I also treat re-render as a first-class flake source: stale element references usually mean I grabbed a node React later replaced, so I re-find rather than cache. Finally, I argue for pushing coverage down — React Testing Library component tests own rendering and validation logic, and the end-to-end suite covers the few journeys that actually cross the API and back.", anchor: "Inn-Flow JD gap — React SPA testing" },
    { track: "interview", type: "mcq", topic: "MULTI-TENANT SAAS", question: "What is the most important category of test that a multi-tenant SaaS application needs and a single-tenant application does not?", options: ["Standard functional regression run once per release", "Tenant isolation testing — proving that one tenant's users, API tokens, and queries can never read, mutate, or aggregate another tenant's data, including through indirect paths like search, reports, exports, shared caches, and background jobs", "Only performance testing, since tenants share hardware", "Browser compatibility across tenants"], answer: 1, explanation: "Cross-tenant data leakage is the defining failure mode of multi-tenant SaaS and it is usually a security incident, not just a bug. Tests must cover the indirect paths — a report, a cached response, an async job, or an ID-guessing request against an endpoint that filters in the UI but not the query. Tenant-specific configuration and feature flags are the other half: the same code path must be verified under different tenant settings.", anchor: "Inn-Flow JD gap — multi-tenant SaaS testing" },
    { track: "interview", type: "written", topic: "DATABASE TESTING", question: "The role names SQL Server and database testing. What does database testing cover beyond running a SELECT to confirm a row exists?", coach: "Go past row spot-checks: state transitions, constraints, transactions, stored procedures, migrations, and how DB checks stay maintainable inside an automated suite.", model: "Row existence is the least interesting part. I verify that an API action produced the right state change across every table it touches — parent, child, audit, and status columns — and that values are correct in type, precision, and rounding, not merely present. I test the constraints themselves: uniqueness, foreign keys, nullability, and cascade behavior, because those are the guardrails that keep bad data out when application validation is bypassed. Where stored procedures or views carry business logic, they need direct tests with boundary inputs, since UI coverage exercises only the happy path through them. Transactions matter too: a failed multi-step operation must roll back cleanly with no orphans. Migrations get a before/after check on row counts, checksums, and a sample of transformed values. In the framework I keep this behind a small data-access layer with parameterized queries and per-test data setup and teardown, so database assertions do not turn into a pile of hard-coded SQL scattered through tests.", anchor: "Inn-Flow JD gap — SQL Server and database testing" },
    { track: "interview", type: "mcq", topic: ".NET API TESTING", question: "You are testing a .NET REST API and your automation stack is Java/REST Assured or JS/Postman. What is the correct framing in an interview?", options: ["You need to rewrite the automation in C# to test a .NET API properly", "The API contract is the interface, so the server's implementation language is largely irrelevant to black-box API testing — what matters is knowing the .NET-specific behaviors you will actually hit: model-binding validation errors and the ProblemDetails/400 response shape, JSON serializer casing and null handling, authentication middleware behavior, and where Swagger/OpenAPI comes from", "Only unit tests written in C# can validate a .NET API", "Postman cannot call .NET endpoints"], answer: 1, explanation: "Black-box API testing works against HTTP and the contract, so REST Assured, Postman, or anything else calls a .NET endpoint fine. The value in knowing it is .NET is predicting its conventions — the standard validation error payload, serializer settings that decide casing and whether nulls are emitted, and the Swagger doc generated from the controllers, which is your source of truth for the contract.", anchor: "Inn-Flow JD gap — testing .NET APIs" },
    { track: "interview", type: "written", topic: "AZURE / CLOUD QA", question: "The stack is Azure. What does a QA engineer need from a cloud environment, and what would you use Azure DevOps pipelines for?", coach: "Stay in the QA lane — environments, secrets, test data, observability, and pipeline stages — rather than claiming cloud administration.", model: "From a QA perspective I need four things from the cloud: environments I can get into and reset, credentials handled properly, telemetry when something fails, and a pipeline that runs my suite. On Azure that maps to App Service or AKS hosting the environment under test, Key Vault holding the database and API credentials the tests pull at run time instead of a checked-in properties file, Azure SQL for the data layer I validate against, and Application Insights or Log Analytics for the request traces and exceptions that turn a failed assertion into a root cause. In Azure DevOps Pipelines I would structure stages the same way I would anywhere: a fast build-and-unit stage, an API and smoke stage on every pull request, a fuller regression stage on merge or nightly, published test results and artifacts on every run, and a quality gate that blocks promotion. I would be clear that I consume these services as a tester and lean on platform engineers for provisioning rather than claiming to administer them.", anchor: "Inn-Flow JD gap — Azure and cloud test environments" },
    { track: "interview", type: "mcq", topic: "PERFORMANCE TESTING", question: "The JD lists JMeter and k6 for performance/load testing. What is the practical difference in choosing between them?", options: ["k6 is simply a rewrite of JMeter with the same GUI workflow", "JMeter is a mature JVM tool with a GUI for building plans and a large plugin/protocol range, which suits complex correlated scenarios and teams who want a visual plan; k6 is a Go-based CLI where the test is JavaScript code with thresholds defined in the script, which fits developer-owned, version-controlled, CI-native load testing — both produce the same kind of result, so choose on team workflow and protocol needs", "k6 cannot express ramp-up or think time", "JMeter cannot run headless in CI"], answer: 1, explanation: "Both run load and report latency percentiles and error rates. The real split is workflow: JMeter's GUI-authored XML plans and deep protocol coverage versus k6's scripted, code-reviewed, threshold-as-pass/fail model that drops naturally into a pipeline stage. Note that JMeter runs headless in CI too — GUI mode is for authoring, not execution.", anchor: "Inn-Flow JD gap — JMeter vs k6" },
    { track: "interview", type: "written", topic: "SHIFT-LEFT", question: "The JD says this role is about preventing bugs, not finding them. What do you actually do differently to prevent defects?", coach: "Name concrete pre-code activities and the artifacts they produce. Prevention is about ambiguity removal and early feedback loops, not about testing harder later.", model: "Prevention happens before code is written, mostly by attacking ambiguity. I join refinement and pick apart acceptance criteria — what happens on the empty state, the duplicate submission, the permission the user does not have, the value at the boundary — and every question I ask that a story cannot answer is a defect that never gets coded. I get those answers written into the criteria as testable statements, in Given/When/Then form where it helps, so developer, product, and QA are working from one definition of done. I review the API contract while it is still a draft, because a wrong status code or a nullable field caught in the spec costs minutes instead of a release. I pair with developers on what their unit and integration tests already cover so my layer adds coverage rather than duplicating it. And I feed production and escaped-defect patterns back into refinement, since the same failure categories recur. The measurable outcome is fewer defects reopened or found late, not just a bigger test suite.", anchor: "Inn-Flow JD gap — prevention and shift-left collaboration" },
    { track: "interview", type: "written", topic: "MENTORING", question: "How do you mentor junior QA engineers and advocate for a quality-first culture across an engineering team?", coach: "Separate the two: mentoring is a concrete skills path with real work attached; culture change is about making quality visible and shared, not about policing developers.", model: "For mentoring I start from where the person actually is and give them owned work rather than tasks. Someone strong at manual testing but new to automation starts by converting their own regression cases into tests in an established pattern, with me reviewing every pull request and explaining the why behind comments, then graduates to owning a page object or an API module, then to reviewing someone else's code. I pair on failure triage specifically, because reading a stack trace and deciding real bug versus flaky test versus environment is the skill that separates a script writer from an engineer. For culture, I make quality visible instead of asking for it — test results and coverage gaps in the pull request, a short quality readout the whole team sees, defect trends surfaced at retro rather than only in a QA meeting. I also make it easy to do the right thing: a suite that runs fast and does not lie, so developers actually use it. Quality-first fails the moment it sounds like QA telling developers they are careless, so I frame it as shared release confidence and let the data carry the argument.", anchor: "Inn-Flow JD gap — mentoring and quality culture" },
    { track: "interview", type: "mcq", topic: "QUALITY METRICS", question: "You must track and report quality metrics to improve release confidence. Which set is most defensible?", options: ["Number of test cases written and number of bugs logged per tester", "Escaped defect rate (defects found in production vs. pre-release), defect removal efficiency by phase, automated test pass and flake rate, mean time to detect and to resolve, and pipeline/regression cycle time — each tied to a decision the team can act on", "Code coverage percentage as the single quality gate", "Total automation count, tracked as a growth target"], answer: 1, explanation: "Volume metrics — cases written, bugs logged, tests automated — reward activity and are trivially gamed. Outcome metrics tie to release confidence: what got out, how fast it was caught, whether the suite can be trusted, and how long the feedback loop takes. Flake rate belongs in the set because an unreliable suite quietly destroys the value of every other number.", anchor: "Inn-Flow JD gap — quality metrics and release confidence" },
    { track: "interview", type: "written", topic: "CONTINUOUS TESTING", question: "What does continuous testing in a CI/CD pipeline mean beyond 'the tests run on every commit'?", coach: "Cover stage design and speed budgets, environment and data provisioning, quality gates, flake policy, and reporting. Emphasize that a slow or untrusted suite gets bypassed.", model: "Continuous testing means every stage of the pipeline gives a trustworthy signal fast enough that people wait for it. I layer it: unit and static checks in seconds on the build, API and contract tests plus a thin UI smoke on every pull request within a few minutes, the full regression and cross-browser run on merge or nightly, and performance and security scans on a scheduled cadence. Each stage needs its environment and data provisioned by the pipeline, not by hand — containerized services or an ephemeral environment, credentials from a secret store, and test data created and cleaned up by the test itself so runs do not collide. Gates have to be real: a failing PR stage blocks the merge, or the pipeline is decoration. That only survives if flake is treated as a defect with an owner — quarantine the test, file it, fix or delete it — because the moment developers start re-running red builds, the gate is gone. And results have to land where people already are: the pull request, the build summary, a channel notification, with artifacts like screenshots, traces, and logs attached so triage does not require running it locally.", anchor: "Inn-Flow JD gap — continuous testing in CI/CD" },
    { track: "interview", type: "written", topic: "TEST STRATEGY", question: "Design an automation strategy for a modern SaaS platform with a React UI, .NET APIs, third-party integrations, and SQL Server. Cover test layers, framework boundaries, data strategy, reporting, and CI gates.", coach: "Answer as an architecture, not a tool list. Assign each risk to the cheapest layer that can prove it, then say who owns the boundary between layers, where data comes from, and what blocks a merge.", model: "I start from risk and assign each one to the cheapest layer that can prove it. Unit and component tests own rendering, validation, and calculation logic — React Testing Library on the front end, xUnit or NUnit on the .NET side. Contract tests own the shape of every API the UI or an integration partner depends on, generated from the OpenAPI spec so a breaking change fails the provider's build rather than a UI test three days later. API tests own business rules, authorization, and persistence: call the endpoint, assert the response, then reconcile the database state. Integration tests own the third-party boundaries with stubbed partners for deterministic runs plus a small scheduled live-contract check to catch upstream drift. End-to-end UI tests are deliberately the smallest layer — the handful of revenue-critical journeys, nothing that a lower layer already proves. Framework boundaries matter as much as the layers: a client layer wraps request specs, auth, and serialization; page objects wrap UI structure; a data-access layer wraps SQL. Tests express intent and never build a raw request or a hard-coded query. Test data is created by the test through APIs or seeded fixtures and torn down after, per-tenant and per-run, so parallel execution and shared environments do not collide. Reporting publishes results, screenshots, traces, and logs into the pull request and build summary, plus a trend view of pass rate, flake rate, and duration so decay is visible before it is fatal. CI gates: unit and static analysis on build, contract plus API plus a thin UI smoke blocking every pull request, full regression and cross-browser on merge or nightly, performance and security on a schedule. If a gate does not block, it is decoration.", anchor: "Inn-Flow JD gap — end-to-end automation strategy" },
    { track: "interview", type: "written", topic: "TOOL SELECTION", question: "How would you choose among Playwright, Cypress, and Selenium for this platform? Address team skills, browser coverage, debugging, API support, parallelism, CI cost, and migration risk.", coach: "Show a decision framework with an explicit recommendation and the condition that would change it. Do not sell a favorite tool — the interviewer is testing judgment, and 'it depends' with no answer is a fail.", model: "I would decide on the team, not the benchmark. Team skills come first: a tool nobody on the team can debug at 2am is a bad tool no matter how good it is, so a JavaScript- and TypeScript-heavy product team points at Playwright or Cypress, while a Java or C# automation group with existing assets points at Selenium. On coverage, Playwright drives Chromium, Firefox, and WebKit from one API, Selenium spans the widest real-browser and grid footprint, and Cypress is strongest inside Chromium. For debugging, Playwright's trace viewer and Cypress's time-travel runner both beat reading a Selenium stack trace, which matters more than most teams admit because triage time dominates the total cost of a suite. For API support, Playwright and Cypress can issue requests natively in the same test, which is how you set up state fast; with Selenium you pair it with REST Assured or an HTTP client. On parallelism and CI cost, Playwright parallelizes out of the box with cheap browser contexts instead of full browsers, Selenium Grid gives control at the price of running infrastructure, and Cypress's efficient parallel orchestration historically leans on its paid dashboard. Migration risk is the deciding constraint whenever a suite already exists: rewriting a working regression suite buys a nicer API and costs months of coverage, so my default is to stop writing new tests in the old tool, build new coverage in the new one, and migrate opportunistically as tests need maintenance anyway. For a greenfield React and .NET platform I would recommend Playwright — native waiting, tracing, parallelism, and API calls in one tool — and I would change that recommendation if the team's real skill base or an existing suite's size made the switching cost higher than the benefit.", anchor: "Inn-Flow JD gap — Playwright vs Cypress vs Selenium selection" },
    { track: "interview", type: "written", topic: "MULTI-TENANT SAAS", question: "How would you prove that one hotel company or property can never read or modify another tenant's data?", coach: "Prove a negative by attacking the boundary, not by testing the happy path. Name the indirect paths, and say what makes the test trustworthy as evidence rather than a demo.", model: "You cannot prove isolation by logging in as one tenant and seeing your own data — that is the happy path. I attack the boundary directly. I create two tenants with known, distinguishable data, then take tenant A's authenticated session or token and aim it at tenant B's resources: direct object references by ID, list and search endpoints, report and export generation, bulk operations, file downloads, and any endpoint that takes a tenant, property, or company identifier as a parameter. The expected result is a 403 or 404 in every case — and I check that the response body leaks nothing either, because a 403 that names the record still confirms it exists. Then I cover the indirect paths, which is where real leaks live: cached responses served to the wrong tenant, background jobs and scheduled reports running under a stale or elevated context, aggregate and analytics queries missing a tenant predicate, notification and email recipients, and anything joined across tables where one join lost the filter. Database-level checks matter too — I run the application's own queries with a tenant context and confirm the SQL actually carries the isolation predicate rather than relying on the UI to filter. I automate these as a permanent tenant-isolation suite that runs on every build, tagged as security-critical, because this is a class of defect where a single regression is an incident, not a bug. And I say plainly what the tests do not prove: they demonstrate isolation for the paths I enumerated, which is why the suite grows with every new endpoint rather than being a one-time exercise.", anchor: "Inn-Flow JD gap — proving tenant isolation" },
    { track: "interview", type: "written", topic: "MULTI-TENANT SAAS", question: "Build a multi-tenant test matrix covering tenant, property, department, user role, feature flag, and environment. How do you keep it from exploding?", coach: "Six dimensions multiply into thousands of combinations. Show that you know full factorial coverage is not the goal and name the technique that replaces it.", model: "The full cross-product of six dimensions is thousands of combinations, so the first thing I say is that exhaustive coverage is not the goal — targeted coverage of the interactions that actually change behavior is. I classify each dimension by what it controls. Role and feature flag are behavior-changing, so they get direct coverage: every role against every permission-guarded action, and each flag tested on, off, and mid-flight where a flag can flip during a session. Tenant and property are isolation-changing, so they get at least a two-tenant, multi-property configuration exercised by the isolation suite rather than repeated through every functional test. Department is usually a data-scoping dimension, so it gets coverage where scoping rules apply and gets ignored where it does not. Environment is a deployment dimension, not a functional one — the same suite runs everywhere, with only the smoke and configuration checks being environment-specific. Then I use pairwise or all-pairs generation across the combinatorial dimensions, because most defects surface from a pair of factors interacting rather than a six-way combination, and I pin the specific high-risk combinations that pairwise might skip — the tenant with every flag enabled, the multi-property company, the read-only role against a destructive endpoint. Structurally that means data-driven tests fed from a matrix definition, not copy-pasted test classes, so adding a role or a flag adds rows rather than files. I also keep a named set of seeded tenant archetypes — single property, multi-property, all flags on, minimal configuration — because reproducible fixtures are what make the matrix runnable in CI instead of aspirational.", anchor: "Inn-Flow JD gap — multi-tenant test matrix design" },
    { track: "interview", type: "written", topic: ".NET API TESTING", question: "How would you validate a .NET API beyond the status code? Cover contract, authentication, authorization, payload, business rules, database state, idempotency, latency, and negative cases.", coach: "A 200 proves the request was accepted, nothing more. Walk each validation layer and say what a failure at that layer would look like in production.", model: "A 200 proves the server accepted the request; it proves nothing about correctness. I validate in layers. Contract first: response shape, field names and casing, types, required versus nullable fields, and enum values against the OpenAPI spec, so a serializer setting change or a renamed property fails here rather than silently breaking a consumer. Authentication next: no token, expired token, malformed token, and a token for the wrong audience should each return 401 rather than 200 or 500. Authorization separately, because it is a different failure: a valid token with insufficient role, and a valid token from another tenant, must be denied on every endpoint including the ones the UI never exposes. Payload correctness means checking values, not presence — money to the right precision and rounding, dates with the right time zone handling, calculated totals recomputed independently in the test rather than echoed back from the response. Business rules get boundary and rule-violation cases: overlapping records, closed periods, negative quantities, and state transitions that should be rejected. Database state is the layer most people skip — after a write I confirm every affected table, including audit and status columns, and after a rejected request I confirm nothing was written, because a rolled-back transaction that leaves an orphan row is a real bug. Idempotency matters wherever retries exist: the same request with the same idempotency key twice must produce one record, and I test the duplicate-delivery path explicitly. Latency gets an assertion against an agreed budget so a query regression shows up as a failing test rather than a support ticket. And negative cases run alongside all of it — malformed JSON, wrong content type, oversized payloads, missing required fields — where the expectation is a clean 400 with the ProblemDetails shape, never a 500 with a stack trace.", anchor: "Inn-Flow JD gap — deep .NET API validation" },
    { track: "interview", type: "written", topic: "PERFORMANCE TESTING", question: "Design a JMeter or k6 plan for a portfolio dashboard or a payroll-processing API. Define workload, unique data, ramp-up, percentiles, throughput, error budget, and stress and soak goals.", coach: "Start from a workload model and a pass/fail threshold, not from a tool. Call out the two mistakes that invalidate most load tests: cached identical data and averaging the response times.", model: "I start from a workload model, not a script. For a portfolio dashboard that means the realistic mix — how many concurrent users at peak, what fraction are loading the dashboard versus drilling into a property versus exporting, and what the think time between actions looks like. For a payroll-processing API it is different in kind: fewer callers, much larger payloads, and a batch that must complete inside a window, so the target is throughput and completion time rather than concurrent-user count. Unique data is the mistake that invalidates most load tests — if every virtual user requests the same property for the same date range, you are load-testing the cache. I parameterize from a CSV or a generated data set so each user hits different tenants, properties, and periods, and I size that data set to the run so it does not wrap around. Ramp-up is gradual — step up over several minutes to a steady state, hold long enough for the system to stabilize, then ramp down — because an instant spike measures cold start rather than sustained capacity. Thresholds go in the plan up front and are stated as percentiles, never averages: p95 under the agreed budget, p99 as the outlier watch, error rate under a defined budget such as a tenth of a percent, and throughput at or above the target requests per second. In k6 those are literal thresholds in the script so the run exits non-zero and fails the pipeline stage. Beyond the baseline load test I run two more shapes. Stress pushes past expected peak in steps to find the knee — where latency turns up and errors begin — so we know the headroom and how the system degrades, ideally by shedding load cleanly rather than collapsing. Soak runs a moderate load for hours to expose what a short test hides: memory growth, connection-pool exhaustion, log-disk pressure, and slow database contention. Throughout, I correlate client-side numbers with server-side telemetry, because the useful output is not 'it was slow' but which layer became the bottleneck.", anchor: "Inn-Flow JD gap — JMeter and k6 plan design" },
    { track: "interview", type: "written", topic: "SECURITY TESTING", question: "How would you test authorization and tenant isolation for financial and payroll data, including horizontal and vertical privilege escalation?", coach: "Define both escalation directions concretely, then describe a systematic, automated approach rather than ad-hoc poking. Payroll raises the stakes on field-level access too.", model: "Two directions, and they fail differently. Horizontal escalation is a user reaching a peer's data at the same privilege level — one manager pulling another property's payroll register, or one employee opening a coworker's pay stub by changing an ID in the URL or request body. Vertical escalation is a user reaching a higher privilege level — a read-only accountant approving a pay run, or a property-level user invoking a company-level endpoint. I test both systematically rather than by poking around. I build an authorization matrix of every endpoint and action against every role, with the expected outcome for each cell, and drive it as a data-driven suite so the matrix is executable and adding an endpoint means adding rows. For each role I take a genuinely authenticated session and attempt every action the matrix says it should not have, and the assertion is a clean denial — not a 500, and not a 200 with an empty list, because an empty list often means the query filtered while the authorization check did not exist. Financial and payroll data adds field-level scope on top of endpoint-level scope: a manager may legitimately see hours and headcount but not salary, tax, or bank details, so I assert the fields in the response, not just access to the resource. I also cover the paths that bypass the UI entirely — direct API calls, exports and report generation, bulk endpoints, and any background job that runs with a service identity, since jobs are where over-broad permissions hide. Rate limiting and audit logging get checked too: every access to payroll data should be attributable, and the audit trail is itself a testable artifact. This whole suite runs on every build and is treated as release-blocking, because in this data class a regression is a compliance incident.", anchor: "Inn-Flow JD gap — authorization and privilege escalation testing" },
    { track: "interview", type: "written", topic: "ARCHITECTURE RISK", question: "What architectural signals would cause you to raise a reliability risk before code reaches test?", coach: "Show that you read designs, not just stories. Name specific structural smells and what failure each one predicts — vague 'I attend design reviews' answers score nothing.", model: "I read designs looking for the shapes that reliably produce production incidents. A synchronous call chain across several services with no timeout, no retry policy, and no fallback means one slow dependency stalls the whole request path — that is a cascading-failure risk before a line is written. A write that spans multiple services or a service plus an external system with no idempotency key and no reconciliation step predicts duplicate records the first time a retry fires. A new query on a large table with no index on the filter columns, or an N+1 pattern hidden behind an ORM, predicts a dashboard that is fine in test data and unusable at a real tenant's volume. Shared mutable state — a cache without a tenant key, a static or singleton holding request-scoped data, a background job assuming single-instance execution — predicts cross-tenant leakage and race conditions the moment the service scales out. No pagination on a list endpoint predicts a timeout for the largest customer. A schema migration that changes a column type in place with no backfill plan and no rollback path predicts a failed deploy with no way back. Missing structured logging, correlation IDs, or metrics predicts an outage nobody can diagnose. And on the process side, a feature with no flag and no gradual rollout means the only mitigation is a full rollback. When I raise one of these I raise it as a specific failure mode with the condition that triggers it and a proposed mitigation, not as an objection — the point is to get a timeout policy or an index added while it costs an hour, and to know what to test hardest if the team accepts the risk anyway.", anchor: "Inn-Flow JD gap — architectural reliability risk review" },
    { track: "interview", type: "written", topic: "INTEGRATION TESTING", question: "A labor record flows into payroll, accounting, and BI. How would you test the whole workflow, including retries, duplicate delivery, partial failure, reconciliation, and eventual consistency?", coach: "Test each hop and the whole chain, and be explicit about the distributed-systems failure modes. Naming eventual consistency is not enough — say how you avoid asserting too early without sprinkling sleeps.", model: "I test the hops individually and then the chain end to end, because a workflow that passes hop by hop can still lose a record at a boundary. Per hop I verify the contract in both directions: the message or payload shape the producer emits, and what the consumer does with every field including the ones it ignores today. End to end I create one labor record with a traceable identifier and follow it through to the payroll calculation, the accounting entry, and the BI aggregate, asserting the values match at each destination rather than merely that a row arrived — a record that lands with the wrong cost center is worse than one that never lands. Then I test the failure modes deliberately. Retries: I make a downstream consumer fail transiently and confirm the retry is bounded, backs off, and eventually succeeds without duplicating the write. Duplicate delivery: I deliver the same message twice, because at-least-once delivery is the norm, and the correct result is one record — this is where I check idempotency keys or dedupe logic actually exist rather than assuming them. Partial failure: I let payroll succeed while accounting fails and assert the system converges rather than silently diverging, either by retrying the failed leg or by parking it somewhere visible — a dead-letter queue that nobody monitors is the same as data loss, so I test that failed messages land there and that they can be replayed. Reconciliation gets its own tests: totals and counts agreed between systems for a period, and a deliberately injected mismatch to confirm the reconciliation report actually catches it instead of reporting clean. For eventual consistency I never assert immediately and never fix it with a fixed sleep — I poll the destination for the expected state with a timeout and a clear failure message, which both removes flake and turns 'the pipeline is slower than the agreed SLA' into a real, actionable failure.", anchor: "Inn-Flow JD gap — end-to-end integration and eventual consistency" },
    { track: "interview", type: "written", topic: "AI-ASSISTED QA", question: "An invoice is coded by an AI-assisted workflow. How would you validate correctness, confidence thresholds, auditability, fallback behavior, and human override?", coach: "Treat the model as a non-deterministic component with a measurable accuracy budget, not as a feature that passes or fails. Separate testing the model's output from testing the system wrapped around it.", model: "I separate two things: evaluating the model's output quality, and testing the system built around it — and the second is where most of the real defects live. For correctness I need a labeled ground-truth set of invoices with known correct coding, deliberately including the hard cases: unusual vendors, multi-line invoices, split allocations, credits, and formats the model has not seen. Because the component is non-deterministic, the pass criterion is an accuracy threshold measured against that set rather than an exact-match assertion, and I track it over time so a model or prompt update that degrades accuracy is caught as a regression — I would insist a model version change re-runs that evaluation before it ships. Confidence thresholds get tested as a routing rule: below the threshold the invoice must go to human review, above it can auto-post, and I test both sides of the boundary plus the boundary value itself. The dangerous case is high confidence and wrong, so I make sure the evaluation set reports confidently-incorrect predictions separately — that number, not overall accuracy, is what should set the threshold. Auditability is straightforwardly testable and non-negotiable for financial data: every AI-coded invoice must record what the model proposed, its confidence, the model version, and who accepted or changed it, and I assert that record exists and survives the subsequent workflow. Fallback behavior covers the service being down, slow, or returning malformed output — the correct result is the invoice queued for human coding, never an auto-post of a garbage value and never a lost invoice. Human override needs to work and to stick: the corrected coding persists, is not silently re-overwritten by a later model run, and is captured as feedback if the system learns from corrections. I would also push for a monitored auto-post rate and correction rate in production, because a rising correction rate is the early signal that the model has drifted against real invoice data.", anchor: "Inn-Flow JD gap — validating an AI-assisted invoice workflow" },
    { track: "interview", type: "written", topic: "MENTORING", question: "How would you mentor a junior QA engineer whose automated tests pass but contain weak assertions and brittle waits?", coach: "Name the two specific problems and the concrete fix for each, then describe the coaching move — teaching the reasoning beats rewriting their code. Green tests that assert nothing are worse than no tests.", model: "First I name why this matters, because a green suite feels like success: a test that asserts the page loaded proves almost nothing, and a test that passes because of a sleep will pass a broken build too. Silent false confidence is worse than no coverage. For weak assertions I teach one question — if this feature broke, would this test go red? Usually the answer exposes it: the test checks that an element exists rather than that the value is correct, or it echoes back the API's own response instead of independently verifying the outcome. I have them write the failing case first, break the feature deliberately, and watch their test stay green. That single exercise teaches more than a code review comment. Then we build the habit of asserting the business outcome — the balance, the status transition, the record in the database — not the presence of a div. For brittle waits I explain the mechanism rather than banning sleeps by decree: a fixed sleep is a guess that is simultaneously too slow on a fast machine and too short on a loaded CI agent, and it never fails for the right reason. We replace it with an explicit wait on the actual condition — element clickable, network call complete, expected text present — and I show them the difference in the failure message, since a well-written wait fails saying what it waited for. I review their pull requests with the reasoning attached rather than a rewrite, because the goal is that the next test does not need the comment. And I would look for whether the framework is making this hard: if the codebase has no wait helpers and no assertion utilities, the junior engineer is not the root cause, and I fix that too.", anchor: "Inn-Flow JD gap — coaching weak assertions and brittle waits" },
    { track: "interview", type: "written", topic: "BEHAVIORAL", question: "Tell us about a time you challenged acceptance criteria early and prevented a defect.", coach: "Pull the actual example from the interview packet — do not invent one here. This card is for the shape: the specific ambiguity you spotted, the question you asked, what the answer changed, and the concrete defect that never happened.", model: "Structure to hit, with the real example supplied from your prep packet: name the story briefly — which feature, which refinement or review, what stage the work was at. State the specific gap you saw in the acceptance criteria, and be concrete about the category, because 'the requirements were vague' is not an answer — it was an unhandled empty state, an undefined behavior at a boundary, a missing permission case, a duplicate-submission path, or two documents that contradicted each other. Say what you did: the question you asked, who you asked, and the fact that you pushed for the answer to be written into the criteria as a testable statement rather than settling for a verbal agreement in a meeting. Then the outcome, which is the part that makes it a prevention story: what would have been built without the question, roughly what it would have cost to catch later, and what the criteria said afterward. Close with the transferable habit — that you review acceptance criteria for the paths nobody wrote down, and that catching ambiguity in refinement is the cheapest defect removal available. Keep the tone collaborative: you clarified a requirement, you did not catch someone being sloppy.", anchor: "Inn-Flow JD gap — behavioral, challenging acceptance criteria" },
    { track: "interview", type: "written", topic: "BEHAVIORAL", question: "Tell us about a release-risk decision where your evidence changed the team's plan.", coach: "Pull the real example from the interview packet. The card is for the shape: what the evidence was, how you framed it as risk rather than opinion, what the team decided, and that you owned the call afterward either way.", model: "Structure to hit, with the real example supplied from your prep packet: set the stage — the release, the deadline pressure, and what the plan was before you spoke up. Then the evidence, which is the whole point of the story: something concrete and checkable — a defect trend, a specific failure with a traced root cause, a coverage gap on a high-value path, a performance number against the budget — not a feeling that it seemed risky. Say how you framed it, because the framing is the skill: risk and business impact in terms the decision-makers cared about, with options attached rather than a veto. Who is affected, what is the likelihood, what would it cost, and here are the choices — ship with a known limitation and a monitor, hold a day for the fix, ship behind a flag to a subset. Then what the team actually decided and why, and be honest if the decision was not the one you recommended, because owning a call you disagreed with and then supporting it is a stronger answer than always being right. Close with the outcome and what you would do the same way: you presented evidence so the team could make an informed trade-off, rather than either quietly absorbing the risk or blocking the release on authority you did not have.", anchor: "Inn-Flow JD gap — behavioral, release-risk decision" },
    { track: "interview", type: "written", topic: "ONBOARDING PLAN", question: "What would your first 30, 60, and 90 days look like if the company's current automated coverage is fragmented?", coach: "Earn credibility before proposing a rewrite. Learn and stabilize first, then build, then scale — and attach a visible deliverable to each phase so it is a plan, not a posture.", model: "Days 1 to 30 are for learning and honest assessment, not for rewriting anything. I meet the engineers, product, and support to learn where defects actually escape and which failures hurt customers most, then inventory what exists: which suites run, which are green, which are quarantined or ignored, what the flake rate is, how long the pipeline takes, and what percentage of it anyone trusts. I run the suites myself and triage failures, because triaging someone else's suite is the fastest way to learn both the product and the framework. The deliverable is a written coverage-and-risk map — what is covered, what is not, and where the highest-risk gaps sit — plus a shortlist of quick wins. In parallel I stabilize: the fastest credibility win in a fragmented suite is making the existing signal trustworthy, so I fix or quarantine the flakiest tests and get the pipeline reporting cleanly. Days 31 to 60 are for building the foundation. I agree a target architecture with the team — the layer model, the framework boundaries, the data strategy, the tool decision — and consolidate rather than adding another fragment, because a fourth framework is how fragmentation happened. I would rather land it as a working vertical slice on one high-value area than as a proposal document: contract and API coverage on a critical service, a small end-to-end journey suite, and both wired into a blocking pipeline gate. The deliverable is that gate plus the pattern other people can follow. Days 61 to 90 are for scaling and making it stick. Coverage expands to the remaining high-risk areas by the agreed pattern, tenant isolation and authorization suites get established as release-blocking, and I add the reporting layer — pass rate, flake rate, escaped defects, cycle time — so quality is visible to people outside QA. By then I want other engineers writing tests in the framework, not just me, and a documented standard plus review habits that keep the suite from decaying again. Throughout, I would say plainly that the plan adjusts after the first 30 days, because a 90-day plan written before seeing the codebase is a guess.", anchor: "Inn-Flow JD gap — 30/60/90 onboarding plan" },
    { track: "interview", type: "written", topic: "CORE COMPETENCIES", question: "The JD names core competencies — Time Management, Dealing with Ambiguity, Composure, Self-Development, Perseverance, Customer Focus, and Drive for Results. How do you prepare for these without rehearsing seven separate speeches?", coach: "Show the efficient prep technique: a small set of real stories, each mapped to 2-3 competencies, rather than one story per competency. Give one concrete QA-flavored example per competency so it's not just abstract advice.", model: "I don't prep one story per competency — I prep 3 to 4 real stories and map each one to whichever competencies it actually demonstrates, since most solid work stories hit several at once. For Dealing with Ambiguity, my go-to is testing against an incomplete requirement and documenting the assumptions I made rather than waiting or guessing silently. For Composure, it's staying methodical during a production incident instead of chasing every theory at once. For Perseverance, it's an intermittent defect I tracked down over several days by narrowing conditions instead of closing it as non-reproducible. For Customer Focus, it's a case where I pushed back on a 'good enough' fix because of the actual end-user impact I'd traced. For Drive for Results, it's a release where I found a way to cover the highest-risk paths under a real time constraint instead of either skipping coverage silently or blowing the deadline. Self-Development and Time Management are usually shown through the same stories, not separate ones — how I closed a skill gap, or how I prioritized when everything looked urgent. The prep goal is a small, reusable story bank, not a script for every keyword.", anchor: "Builders Mutual JD gap — core competencies (behavioral prep)", employers: ["builders-mutual"] },
];

const codingDrills = [
    { category: "LABCORP-STYLE", title: "Print every letter of a name", prompt: "Given a name, write Java code that visits and prints each letter in order. Start with the input \"PETER\" and make the solution work for any name.", listening: "a loop, charAt or a character array, and a clear explanation of the index boundary", hint: "A String has a length and a zero-based character at each index.", solution: "String name = \"PETER\";\nfor (int i = 0; i < name.length(); i++) {\n    System.out.println(name.charAt(i));\n}" },
    { category: "DELOITTE-STYLE", title: "Reverse letters, preserve whitespace", prompt: "Write Java code to reverse the non-whitespace characters in a string while keeping every whitespace character in its original position. Example: \"a b c\" → \"c b a\".", listening: "separating whitespace from content, preserving positions, and calling out an empty or all-whitespace case", hint: "First collect non-whitespace characters. Walk the original string again and replace only non-whitespace positions from the reversed collection.", solution: "String input = \"a b c\";\nStringBuilder letters = new StringBuilder();\nfor (char c : input.toCharArray()) {\n    if (!Character.isWhitespace(c)) letters.append(c);\n}\nletters.reverse();\nStringBuilder result = new StringBuilder();\nint index = 0;\nfor (char c : input.toCharArray()) {\n    result.append(Character.isWhitespace(c) ? c : letters.charAt(index++));\n}\nSystem.out.println(result);" },
    { category: "LUXOFT-STYLE API", title: "Calculate settled totals by currency", prompt: "Given a List<TradeResult> with tradeId, status, currency, and BigDecimal amount, return a Map<String, BigDecimal> of totals for SETTLED trades. Reject duplicate IDs and invalid records. Explain your tests.", listening: "filtering by status, BigDecimal aggregation, validation policy, and tests for multiple currencies, duplicates, nulls, and precision", hint: "Use a Set for seen trade IDs and a Map<String, BigDecimal> for totals. State whether invalid records are rejected or collected as validation errors.", solution: "static Map<String, BigDecimal> calculateSettledTotals(List<TradeResult> results) {\n    Set<String> seenIds = new HashSet<>();\n    Map<String, BigDecimal> totals = new LinkedHashMap<>();\n    for (TradeResult trade : results) {\n        if (trade == null || trade.getTradeId() == null ||\n                !seenIds.add(trade.getTradeId())) {\n            throw new IllegalArgumentException(\"Invalid or duplicate trade\");\n        }\n        if (\"SETTLED\".equals(trade.getStatus())) {\n            if (trade.getCurrency() == null || trade.getAmount() == null ||\n                    trade.getAmount().signum() < 0) {\n                throw new IllegalArgumentException(\"Invalid settled trade\");\n            }\n            totals.merge(trade.getCurrency(), trade.getAmount(), BigDecimal::add);\n        }\n    }\n    return totals;\n}" },
    { category: "JAVA CORE", title: "Find duplicate characters", prompt: "Given a string, print each character that appears more than once. Explain whether you want to print a duplicate once or every repeated occurrence.", listening: "a Set or Map, an explicit policy for output, and case-sensitivity as a stated assumption", hint: "A frequency map answers how many times each character occurs. A LinkedHashMap can preserve first-seen order.", solution: "String input = \"selenium\";\nMap<Character, Integer> counts = new LinkedHashMap<>();\nfor (char c : input.toCharArray()) {\n    counts.put(c, counts.getOrDefault(c, 0) + 1);\n}\ncounts.forEach((character, count) -> {\n    if (count > 1) System.out.println(character);\n});" },
    { category: "JAVA CORE", title: "Check for a palindrome", prompt: "Write a method that returns true when a string reads the same forward and backward. State whether you ignore case or whitespace.", listening: "normalization assumptions, two-pointer logic or a reversed comparison, and a useful edge case", hint: "Compare the first and last characters, then move both pointers toward the middle.", solution: "static boolean isPalindrome(String value) {\n    String input = value.replaceAll(\"\\\\s+\", \"\").toLowerCase();\n    int left = 0, right = input.length() - 1;\n    while (left < right) {\n        if (input.charAt(left++) != input.charAt(right--)) return false;\n    }\n    return true;\n}" },
    { category: "DELOITTE-STYLE", title: "Find the second-largest salary", prompt: "Write a SQL query that returns the second-largest distinct salary from an employee table. Explain what happens if there is no second value.", listening: "distinctness, a clear subquery or ranking approach, and the empty-result edge case", hint: "Find the maximum salary below the overall maximum salary.", solution: "SELECT MAX(salary) AS second_highest\nFROM employees\nWHERE salary < (SELECT MAX(salary) FROM employees);" },
    { category: "JAVA CORE", title: "Reverse a string", prompt: "Write a Java method to reverse a string without changing the original input object. Mention the simplest library-backed solution and how you would do it manually.", listening: "String immutability, StringBuilder, and one sentence about a two-pointer or loop alternative", hint: "StringBuilder has a reverse operation and returns a new String when you call toString().", solution: "static String reverse(String input) {\n    return new StringBuilder(input).reverse().toString();\n}" },
    { category: "LUXOFT-STYLE API", title: "POST and deserialize a trade", prompt: "Using REST Assured, POST a TradeRequest POJO to /api/trades with an API key, assert 201 and the Location header, deserialize the body to TradeResult, and verify the returned money value without floating-point loss.", listening: "given/when/then structure, request serialization, contract assertions before extraction, POJO deserialization, BigDecimal comparison, and a useful negative follow-up", hint: "Send the POJO with contentType(JSON), validate before extract().as(...), and compare BigDecimal with compareTo when scale is not part of the contract.", solution: "TradeRequest request = new TradeRequest(\"AAPL\", \"BUY\", 10, new BigDecimal(\"189.50\"));\nTradeResult result = given()\n        .header(\"X-API-KEY\", \"drill-key\")\n        .contentType(ContentType.JSON)\n        .body(request)\n.when()\n        .post(\"/api/trades\")\n.then()\n        .statusCode(201)\n        .header(\"Location\", notNullValue())\n        .contentType(ContentType.JSON)\n        .extract().as(TradeResult.class);\nassertEquals(0, new BigDecimal(\"189.50\").compareTo(result.getPrice()));\nassertEquals(\"NEW\", result.getStatus());\n// Follow-ups: missing API key -> 401; invalid quantity -> agreed 4xx + field error." }
];

